// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Hukukun temel dalları, yargı ilkeleri ve insan hakları belgeleri tarihi (masumiyet karinesi, normlar hiyerarşisi, Magna Carta, İHEB, AİHS) (orta).
const ozSocialscience19Orta = <(String, String, List<String>, String)>[
  ('Aşağıdaki durumlardan hangisi kamu hukukuna değil özel hukuka girer?', 'İki kişi arasında yapılan kira sözleşmesinden doğan uyuşmazlık', ['Vergi borcunu ödemeyen kişiye idare tarafından ceza kesilmesi', 'Bir kamu görevlisinin disiplin soruşturmasına uğraması', 'Seçim sonuçlarına itiraz edilmesi'], 'Özel hukukta taraflar eşit konumdadır; kira sözleşmesi bu alanın tipik bir örneğidir.'),
  ('Kamu hukuku ile özel hukuk ayrımında temel ölçüt aşağıdakilerden hangisidir?', 'İlişkide devletin üstün yetkili kamu gücü olarak bulunup bulunmaması', ['Hukuk kuralının yazılı bir metinde yer alıp almaması', 'Uyuşmazlığın çözümünde kullanılan mahkemelerin sayısı', 'Hukuk kuralının yürürlüğe girdiği tarihin eski veya yeni olması'], 'Kamu hukukunda devlet egemenlik yetkisiyle yer alır; özel hukukta taraflar eşittir.'),
  ('Ayşe, komşusunun bahçesinde bulunan ağacı kendi sözleşmesine dayanarak kesmesi için komşusuyla anlaşıyor. Bu ilişki hangi hukuk dalının alanına girer?', 'Özel hukuk', ['Anayasa hukuku', 'Ceza muhakemesi hukuku', 'İdare hukuku'], 'İki bireyin eşit konumda yaptığı anlaşma özel hukuk ilişkisidir.'),
  ('Bir belediyenin imar planı kapsamında verdiği yapı ruhsatının iptali için açılacak dava hangi yargı kolunda görülür?', 'İdari yargı', ['Adli yargı', 'Anayasa yargısı', 'Uluslararası yargı'], 'Kamu idaresinin işlemlerinin iptali istemleri idari yargıda görülür.'),
  ('Satın aldığı cep telefonunun ayıplı çıkması üzerine satıcıya karşı hak arayan tüketici hangi hukuk dalının koruması altındadır?', 'Tüketici hukuku', ['Anayasa yargısı', 'Vergi usul hukuku', 'Uluslararası insancıl hukuk'], 'Tüketici hukuku, ayıplı mal ve hizmetlere karşı tüketiciyi korumayı amaçlar.'),
  ('Medeni Kanun\'a göre evlenme için aranan olağan yaş kaç olarak belirlenmiştir?', '17 yaşını doldurmuş olmak', ['18 yaşını doldurmuş olmak', '16 yaşını doldurmuş olmak', '15 yaşını doldurmuş olmak'], 'Olağan evlenme yaşı 17\'dir; olağanüstü durumlarda 16 yaşını dolduran kişiler için hâkim izni aranır.'),
  ('Medeni Kanun\'a göre fiil ehliyetine sahip olabilmek için hangi koşullar birlikte aranır?', 'Ergin olmak, ayırt etme gücüne sahip olmak, kısıtlı bulunmamak', ['Doğmuş olmak, ad sahibi olmak, ikametgâh edinmiş olmak', 'Evli olmak, çalışıyor olmak, mal sahibi olmak', 'Vatandaş olmak, okur-yazar olmak, sabıkasız olmak'], 'Fiil ehliyeti için erginlik, ayırt etme gücü ve kısıtlı olmama koşulları gerekir.'),
  ('"İspat yükü" kavramı hukukta neyi ifade eder?', 'Bir hakkı iddia eden tarafın iddiasını kanıtlama yükümlülüğünü', ['Mahkemenin tarafsız davranma yükümlülüğünü', 'Davalının her durumda kendi masumiyetini kanıtlamasını', 'Tanıkların doğruyu söyleme yükümlülüğünü'], 'Medeni Kanuna göre, kural olarak, hakkını iddia eden kişi bu hakkın dayanağı olan olguları ispatla yükümlüdür.'),
  ('Medeni Kanun\'daki "dürüstlük kuralı" ilkesi aşağıdakilerden hangisini ifade eder?', 'Herkesin haklarını kullanırken ve borçlarını yerine getirirken dürüst davranması gerektiğini', ['Hâkimin her davada tarafların ahlaki durumunu araştırmasını', 'Tarafların sözleşmeyi yalnızca yazılı yapmasını', 'Devletin vatandaşa karşı yalnızca doğruyu söylemesini'], 'Dürüstlük kuralı, hakların kullanılmasında ve borçların ifasında dürüst davranmayı gerektirir.'),
  ('Ceza hukukunda "kıyas yasağı" ne demektir?', 'Kanunda açıkça suç sayılmayan bir fiile benzerlik yoluyla ceza verilememesi', ['Aynı suçu işleyen herkese eşit ceza verilmesi zorunluluğu', 'Hâkimin suçları birbirleriyle karşılaştırıp ceza belirlemesi', 'Suç işleyenin geçmiş sabıkasının cezaya etki etmesi'], 'Kıyas yasağı, kanunda yazılı olmayan fiillere benzerlik yoluyla ceza verilmesini engeller.'),
  ('"Cezanın şahsiliği" ilkesi ne anlama gelir?', 'Kimsenin başkasının işlediği fiilden dolayı cezalandırılamaması', ['Cezanın kişinin mesleğine göre belirlenmesi', 'Cezanın yalnızca bireysel yaşam alanında infaz edilmesi', 'Mağdurun cezanın miktarını belirleyebilmesi'], 'Ceza sorumluluğu şahsîdir; kimse başkasının fiilinden dolayı sorumlu tutulamaz.'),
  ('Meşru müdafaa durumunda kişinin eylemi neden cezalandırılmaz?', 'Haksız bir saldırıyı gereken ölçüde uzaklaştırmak için yapılan fiil hukuka uygunluk nedenidir', ['Saldırgan kişi her koşulda zaten cezalandırılacağı için', 'Savunma yapan kişinin devlet memuru sayılması nedeniyle', 'Savunmanın yalnızca geceleri yapılmasına izin verilmesi nedeniyle'], 'Meşru müdafaa, hukuka uygunluk nedenlerinden biridir ve saldırıyı savuşturma ölçüsünü aşmamak gerekir.'),
  ('Bir fiilin sonucunu öngörerek ve isteyerek işlenmesi ceza hukukunda ne olarak adlandırılır?', 'Kast', ['Taksir', 'Zorunluluk hâli', 'Haksız tahrik'], 'Kast, suçun kanuni tanımındaki unsurların bilerek ve isteyerek gerçekleştirilmesidir.'),
  ('Dikkat ve özen yükümlülüğüne aykırılık sonucu istenmeden meydana gelen suç hâli ne ad alır?', 'Taksir', ['Kast', 'Teşebbüs', 'İştirak'], 'Taksirde fail, sonucu istemez ancak dikkat ve özen yükümlülüğüne aykırı davranır.'),
  ('Ceza yargılamasında "tabii hâkim ilkesi" neyi güvence altına alır?', 'Kimsenin kanunen belirlenen mahkeme dışında bir mahkemece yargılanmamasını', ['Hâkimin yalnızca doğal hukuk kurallarını uygulamasını', 'Her davaya mutlaka tek bir hâkimin bakmasını', 'Hâkimin davadaki tarafları kendisinin seçmesini'], 'Tabii hâkim ilkesi, olaydan önce kanunla belirlenmiş mahkemece yargılanma hakkıdır.'),
  ('Mahkeme kararlarının gerekçeli yazılması hangi amaca hizmet eder?', 'Kararın nedenlerinin anlaşılmasını ve denetlenebilmesini sağlar', ['Kararın daha hızlı infaz edilmesini sağlar', 'Hâkimin davadan sorumlu tutulmasını engeller', 'Tarafların itiraz hakkını ortadan kaldırır'], 'Gerekçe, yargı kararlarının keyfî olmadığını gösterir ve üst mahkemece denetimi mümkün kılar.'),
  ('Duruşmaların kural olarak herkese açık yapılması ilkesi (aleniyet) hangi yararı sağlar?', 'Yargılamanın kamuoyu denetimine açık olmasını', ['Yargılama giderlerinin azalmasını', 'Tarafların birbirleriyle konuşmasını yasaklamayı', 'Kararın gizli saklı verilmesini'], 'Aleniyet, yargıya duyulan güveni artırır ve kamuoyu denetimi imkânı doğurur.'),
  ('Hâkimlerin bağımsızlığı ilkesi aşağıdakilerden hangisini ifade eder?', 'Hâkimlerin görevlerinde hiçbir organ veya kişiden talimat almadan vicdani kanaatiyle karar vermesini', ['Hâkimlerin dilediği kanunu uygulama serbestisine sahip olmasını', 'Hâkimlerin mahkeme kararlarını yalnızca kendi tercihine göre infaz etmesini', 'Hâkimlerin devlet yönetimine tamamen kayıtsız kalmasını'], 'Hâkimler, Anayasa, kanun ve hukuka uygun vicdani kanaatlerine göre karar verir.'),
  ('Savcıların ve hâkimlerin meslekte atanması, terfii gibi özlük işlerini yürüten kurul hangisidir?', 'Hâkimler ve Savcılar Kurulu', ['Yüksek Seçim Kurulu', 'Rekabet Kurulu', 'Sayıştay Başkanlar Kurulu'], 'Hâkimler ve Savcılar Kurulu, hâkim ve savcıların mesleğe kabul, atama ve disiplin işlerini yürütür.'),
  ('Soruşturma aşamasında tutuklama kararı vermeye yetkili makam hangisidir?', 'Sulh ceza hâkimi', ['Cumhuriyet savcısı', 'Kolluk amiri', 'Noter'], 'Tutuklama gibi koruma tedbirleri yargı kararıyla uygulanır; soruşturmada bu karar sulh ceza hâkimince verilir.'),
  ('Boşanma davası açmak isteyen bir çifte ait davaya hangi mahkemede bakılır?', 'Aile mahkemesi', ['İş mahkemesi', 'Tüketici mahkemesi', 'Ağır ceza mahkemesi'], 'Boşanma ve velayet gibi aile hukuku uyuşmazlıkları aile mahkemelerinde görülür.'),
  ('İşten haksız çıkarıldığını düşünen bir işçinin işe iade davasını açacağı mahkeme hangisidir?', 'İş mahkemesi', ['Aile mahkemesi', 'Asliye ceza mahkemesi', 'Anayasa Mahkemesi'], 'İşçi-işveren uyuşmazlıkları iş mahkemelerinde çözülür.'),
  ('Medeni Kanun\'a göre yasal mal rejimi aşağıdakilerden hangisidir?', 'Edinilmiş mallara katılma rejimi', ['Mal ayrılığı rejimi', 'Paylaşmalı mal ortaklığı rejimi', 'Mal ortaklığı rejimi'], 'Evlilik içinde mal rejimi sözleşmesi yapılmamışsa edinilmiş mallara katılma rejimi uygulanır.'),
  ('Hukukun kaynakları arasında yer alan "örf ve âdet hukuku" neyi anlatır?', 'Uzun süre aynı biçimde uygulanıp hukuken bağlayıcı sayılan davranış kurallarını', ['Meclis tarafından çıkarılan yazılı kuralları', 'Mahkemelerin tek bir davada verdiği kararları', 'Devletler arasında imzalanan antlaşmaları'], 'Örf ve âdet, yazılı olmayan ancak toplum tarafından uzun süre uygulanıp bağlayıcı sayılan kurallardır.'),
  ('Yargı organlarının benzer olaylarda verdiği kararlardaki ortak hukuki yaklaşıma ne ad verilir?', 'İçtihat', ['Kanunilik', 'Zamanaşımı', 'Yetki'], 'İçtihat, mahkeme kararlarıyla oluşan hukuki görüş ve uygulama birliğidir.'),
  ('Bir vatandaş, başka bir kişinin dikkatsizliği sonucu aracının zarar görmesi üzerine tazminat talep ediyor. Bu uyuşmazlık hangi hukuk dalına girer?', 'Borçlar hukuku', ['Anayasa hukuku', 'Uluslararası kamu hukuku', 'Seçim hukuku'], 'Başkasına kusurlu ve hukuka aykırı bir davranışla zarar verme haksız fiil sayılır ve Borçlar Hukukunda düzenlenir.'),
  ('Kanunların geriye yürümezliği ilkesi ne anlama gelir?', 'Bir kanunun yürürlüğe girmeden önceki olaylara uygulanmamasını', ['Kanunun yalnızca eski olaylara uygulanmasını', 'Kanunun mahkeme kararıyla geçersiz sayılmasını', 'Kanunun zamanla otomatik olarak değişmesini'], 'Hukuk güvenliğini sağlamak için kanunlar kural olarak yürürlüğe girdikleri tarihten önceki olaylara uygulanmaz.'),
  ('Ergin olmayan ve ana babası bulunmayan çocuk için çocuğun menfaatini korumak üzere atanan kişiye ne ad verilir?', 'Vasi', ['Miras bırakan', 'Kayyum olmayan temsilci', 'Borçlu'], 'Vesayet altındaki kişinin işlerini yürütmek üzere atanan kişi vasidir.'),
  ('Bir kişinin ölümü hâlinde mal varlığının kanundan kaynaklanan hâllerde kimlere geçeceğini düzenleyen hukuk dalı hangisidir?', 'Miras hukuku', ['Vergi hukuku', 'Ceza hukuku', 'İdare hukuku'], 'Miras hukuku, ölüm hâlinde mal varlığının kimlere geçeceğini düzenler.'),
  ('Kamulaştırma işleminin hukuka uygun olması için hangi koşul gereklidir?', 'Kamu yararı bulunması ve karşılığının ödenmesi', ['Mal sahibinin her durumda rızasının alınması', 'Bedelin ödenmeksizin devlete geçmesi', 'Yalnızca yabancı malların kamulaştırılması'], 'Kamulaştırma, kamu yararı kararına ve gerçek karşılığın ödenmesine dayanmalıdır.'),
  ('Bir kişi, belediyenin kendisine vermediği ruhsat nedeniyle zarar görmüştür. Bu zararın giderilmesi için ilk başvuracağı yargı kolu hangisidir?', 'İdari yargı', ['Askeri yargı', 'Uluslararası yargı', 'Seçim yargısı'], 'İdare işlemlerinden doğan zararlar için idari yargıda tam yargı davası açılır.'),
  ('Normlar hiyerarşisine göre bir yönetmelik hükmü kanun hükmüyle açıkça çeliştiğinde hangi hukuki sonuç ortaya çıkar?', 'Yönetmelik hükmü geçersiz sayılır ve uygulanmaz', ['Kanun hükmü idare tarafından askıya alınır', 'Yönetmelik yeni tarihli olduğu için öncelikle uygulanır', 'Her iki norm da yürürlükten kalkarak boşluk doğar'], 'Normlar hiyerarşisinde alt basamaktaki yönetmelik üst basamaktaki kanuna aykırı olamaz; aykırılık hâlinde idari yargı iptal kararı verebilir.'),
  ('On altı yaşındaki ayırt etme gücüne sahip bir lise öğrencisi, yasal temsilcisinin izni olmadan kendi adına karşılıksız bir burs bağışını kabul edebilir mi?', 'Evet, karşılıksız kazanım sağladığı için kabul edebilir', ['Hayır, on sekiz yaşından küçükler hiçbir işlem yapamaz', 'Hayır, mahkeme kararı olmadan bağış sözleşmesi kurulamaz', 'Evet, ancak yalnızca ticari şirket kurmak amacıyla yapabilir'], 'Sınırlı ehliyetsizler, yasal temsilcilerinin rızası olmadan kendilerini borç altına sokmayan karşılıksız kazandırmaları tek başlarına kabul edebilirler.'),
  ('Medeni hukukta bir kişinin belirli bir mal üzerinde fiili hakimiyet kurmuş olmasını ifade eden kavram ile o malın hukuki sahibi olmasını ifade eden kavram ayrımı nasıl yapılır?', 'Fiili hakimiyet zilyetlik, hukuki sahiplik ise mülkiyettir', ['Fiili hakimiyet irtifak, hukuki sahiplik ise rehindir', 'Fiili hakimiyet mülkiyet, hukuki sahiplik ise zilyetliktir', 'Fiili hakimiyet vesayet, hukuki sahiplik ise velayettir'], 'Zilyetlik bir eşya üzerindeki fiili egemenliği ifade eder; örneğin kiracı kiraladığı evin zilyedi iken malik evin mülkiyet hakkına sahiptir.'),
  ('Borçlar hukukunda "sözleşme özgürlüğü" ilkesinin kanunla sınırlandırıldığı temel ölçütler arasında hangisi yer alır?', 'Emredici hukuk kurallarına, ahlaka ve kamu düzenine uygunluk', ['Tarafların aynı il sınırları içinde ikamet etmesi zorunluluğu', 'Sözleşmenin her koşulda noter huzurunda imzalanması şartı', 'Taraflardan en az birinin tacir sıfatını taşıması gerekliliği'], 'Taraflar diledikleri konuda sözleşme yapabilirler ancak bu sözleşmeler kanunun emredici hükümlerine, kamu düzenine, kişilik haklarına ve ahlaka aykırı olamaz.'),
  ('Bir kimsenin hukuka aykırı ve kusurlu bir davranışıyla başka bir kişiye zarar vermesi sonucu ortaya çıkan borç kaynağına ne ad verilir?', 'Haksız fiil', ['Sebepsiz zenginleşme', 'Vekaletsiz iş görme', 'Tek taraflı hukuki işlem'], 'Haksız fiil sorumluluğunun doğması için hukuka aykırı fiil, kusur, zarar ve fiil ile zarar arasında uygun illiyet bağı bulunması gerekir.'),
  ('Bir bankanın yanlışlıkla müşteri A\'nın hesabına yatıracağı parayı müşteri B\'nin hesabına aktarması durumunda, B\'nin haklı bir sebep olmaksızın mal varlığındaki bu artışı geri verme borcu hangi borç kaynağından doğar?', 'Sebepsiz zenginleşme', ['Haksız fiil sorumluluğu', 'Kusursuz tehlike sorumluluğu', 'Sözleşmeden doğan kefalet borcu'], 'Haklı bir hukuki neden olmaksızın bir başkasının mal varlığından zenginleşen kişi, bu zenginleşmeyi sebepsiz zenginleşme hükümlerine göre iade etmekle yükümlüdür.'),
  ('Borçlar hukukunda borçlunun borcunu hiç veya gereği gibi yerine getirmemesi durumunda değil, vadesi geldiği hâlde zamanında ifa etmemekte gecikmesi hangi kavramla ifade edilir?', 'Borçlu temerrüdü', ['Alacaklının ibrası', 'Borcun yenilenmesi', 'Kusursuz imkansızlık'], 'Borçlu temerrüdü, muaccel (vadesi gelmiş) ve ifası mümkün bir borcun borçlu tarafından zamanında yerine getirilmemesi durumudur.'),
  ('Ticaret hukukunda tacir olmanın bağlandığı sonuçlardan biri olan "basiretli bir iş insanı gibi hareket etme yükümlülüğü" neyi ifade eder?', 'Ticari faaliyetlerde objektif bir özen ve öngörü göstermek', ['Yalnızca devlet bankaları aracılığıyla ticari kredi kullanmak', 'Tüm ticari uyuşmazlıkları mutlaka tahkim yoluyla çözümlemek', 'Ticari işletmenin yıllık karının yarısını yedek akçe ayırmak'], 'Tacir, ticari işletmesiyle ilgili tüm işlerinde aynı alandaki tedbirli ve dikkatli bir tacirden beklenen yüksek özen düzeyini göstermek zorundadır.'),
  ('Ticaret hukukunda belirli bir hakkın senede sıkı sıkıya bağlandığı ve bu hakkın senet olmaksızın başkasına devredilemediği veya ileri sürülemediği poliçe, bono ve çek gibi belgelere ne ad verilir?', 'Kıymetli evrak', ['Adi yazılı sözleşme', 'Resmi sicil kayıtları', 'İdari tahakkuk belgeleri'], 'Kıymetli evrakta hak ile senet bütünleşmiştir; hakkı talep etmek veya devretmek için senedin ibrazı ve teslimi gerekir.'),
  ('Anonim ve limited gibi sermaye şirketlerini, kollektif şirket gibi şahıs şirketlerinden ayıran en temel sorumluluk özelliği hangisidir?', 'Ortakların şirket borçlarından kural olarak koydukları sermaye ile sınırlı sorumlu olmaları', ['Ortakların tamamının şirket yönetim kurulunda eşit oy hakkına zorunlu olarak sahip olması', 'Şirket borçlarından dolayı ortakların kişisel mal varlıklarıyla sınırsız sorumlu tutulması', 'Sermaye şirketlerinin yalnızca kamu kurumları tarafından kurulabilmesi zorunluluğu'], 'Sermaye şirketlerinde şirket tüzel kişiliği borçlarından kendi mal varlığıyla sorumludur; ortakların sorumluluğu taahhüt ettikleri sermaye payıyla sınırlıdır.'),
  ('İş hukukunda "işçiyi koruma ilkesi" doğrultusunda bir iş sözleşmesi hükmünde tereddüt yaşandığında hakimin uygulaması gereken temel yorum kuralı nedir?', 'İşçi lehine yorum ilkesi', ['İşveren menfaatini öncelikli kılma', 'Sözleşmeyi tamamen geçersiz sayma', 'İdari makamın görüşünü bağlayıcı kabul etme'], 'İş hukuku, ekonomik açıdan zayıf konumda bulunan işçiyi korumayı amaçladığından mevzuat veya sözleşme hükümlerindeki belirsizlikler işçi yararına yorumlanır.'),
  ('İş hukukunda işçinin aynı işverene bağlı olarak belirli bir süreyi aşan çalışması sonucunda haklı neden olmadan işten çıkarılması veya kanunda sayılan diğer durumlarda hak kazandığı tazminata ne ad verilir?', 'Kıdem tazminatı', ['Manevi tazminat bedeli', 'Haksız rekabet tazminatı', 'Kamulaştırma bedeli'], 'Kıdem tazminatı, işçinin en az bir yıl çalıştıktan sonra kanunda öngörülen koşullarla iş sözleşmesinin sona ermesi hâlinde çalıştığı her tam yıl için hak ettiği ödemedir.'),
  ('İş hukukunda işçilerin ekonomik ve sosyal haklarını korumak amacıyla bir araya gelerek oluşturdukları örgütlenme ile işveren karşısında çalışma şartlarını belirlemek için yürüttükleri görüşme süreci hangi kavramlarla ifade edilir?', 'Sendika ve toplu iş sözleşmesi', ['Meslek odası ve idari sözleşme', 'Ticaret borsası ve rekabet anlaşması', 'Kooperatif ve imtiyaz sözleşmesi'], 'Sendikalaşma ve toplu iş sözleşmesi hakkı, işçilerin bireysel olarak ulaşamayacakları çalışma ve ücret standartlarını birlikte müzakere etmelerini sağlar.'),
  ('Ceza hukukunda "suçun manevi unsuru" kapsamında kişinin suçun kanuni tanımındaki unsurları bilerek ve isteyerek gerçekleştirmesi hangi kavramla tanımlanır?', 'Kast', ['Taksir', 'Haksız tahrik', 'Meşru savunma'], 'Kast, failin suç oluşturan eylemi bilerek ve sonucunu isteyerek işlemesidir; taksir ise dikkat ve özen yükümlülüğüne aykırılık sonucu öngörmeden zarara yol açmaktır.'),
  ('Kendisine yönelik haksız ve halen devam eden bir saldırıyı, o andaki durum ve koşullara göre saldırıyla orantılı biçimde defetmek zorunda kalan kişinin bu fiilinden dolayı ceza almamasını sağlayan hukuka uygunluk nedeni hangisidir?', 'Meşru savunma', ['Gönüllü vazgeçme', 'Etkin pişmanlık', 'İzin verilen risk'], 'Meşru savunma (meşru müdafaa), kişinin kendisine veya başkasına yönelmiş haksız bir saldırıyı orantılı güçle önlemesi hâlinde fiili hukuka uygun kılar.'),
  ('Ceza hukukunda "şüpheden sanık yararlanır" (in dubio pro reo) ilkesi, mahkemenin yargılama sonunda hangi kararı vermesini gerektirir?', 'Suçun işlendiği her türlü şüpheden uzak biçimde kanıtlanamazsa beraat kararı verilmesi', ['Delil yetersizliği durumunda sanığa en alt sınırdan hapis cezası uygulanması', 'Şüpheli durumlarda davanın zamanaşımı doluncaya kadar ertelenmesi', 'Sanığın masum olduğunu kendi delilleriyle kesin olarak ispatlamasının istenmesi'], 'Şüpheden sanık yararlanır ilkesi masumiyet karinesinin doğrudan bir sonucudur; mahkumiyet ancak kesin ve inandırıcı delillerle mümkündür.'),
  ('İdare hukukunda idarenin hukuka aykırı bir işleminin mahkeme kararıyla geçmişe etkili olarak ortadan kaldırılması amacıyla açılan dava türü hangisidir?', 'İptal davası', ['Tam yargı davası', 'Tespit davası', 'İcra inkar tazminatı davası'], 'İptal davası, menfaati ihlal edilen kişilerin hukuka aykırı idari işlemlerin yetki, şekil, sebep, konu ve maksat yönlerinden yargısal denetimini sağlayarak ortadan kaldırılmasını amaçlar.'),
  ('İdare hukukunda idarenin hizmet kusuru veya kusursuz sorumluluk ilkeleri gereğince bireylere verdiği maddi veya manevi zararların tazmin edilmesi için açılan dava türü nedir?', 'Tam yargı davası', ['İptal davası', 'Menfi tespit davası', 'Ortaklığın giderilmesi davası'], 'Tam yargı davası, idari eylem ve işlemlerden dolayı kişisel hakları doğrudan zarar görenlerin maddi ve manevi zararlarının giderilmesini talep ettikleri davadır.'),
  ('İdari işlemlerin hukuka uygun olup olmadığının incelenmesinde idare mahkemelerinin esas aldığı beş temel unsur hangileridir?', 'Yetki, şekil, sebep, konu ve maksat', ['Kast, taksir, kusur, zarar ve illiyet', 'Öneri, kabul, ehliyet, bedel ve teslim', 'Mülkiyet, zilyetlik, rehin, irtifak ve tapu'], 'Bir idari işlemin hukuka uygun sayılabilmesi için yetkili makamca, öngörülen şekle uyularak, geçerli bir sebebe dayanarak, hukuka uygun bir konuda ve kamu yararı maksadıyla tesis edilmesi gerekir.'),
  ('Anayasa hukukunda "sert anayasa" kavramı hangi anayasa türünü tanımlar?', 'Değiştirilmesi olağan kanunlara göre daha zor usullere ve nitelikli çoğunluklara bağlanmış anayasalar', ['Yalnızca tek bir siyasi partinin programına göre hazırlanmış anayasalar', 'Değiştirilmesi hiçbir koşulda yasama organının gündemine alınamayan anayasalar', 'Ülkedeki tüm medeni ve ticari kanun hükümlerini tek metinde toplayan anayasalar'], 'Sert anayasalar, nitelikli parlamento çoğunluğu, halk oylaması veya değiştirilemez maddeler gibi özel güvencelerle anayasal istikrarı korur.'),
  ('Anayasa hukukunda yasama, yürütme ve yargı yetkilerinin farklı organlar arasında paylaştırılarak birbirini dengelemesi ve denetlemesi sistemine ne ad verilir?', 'Kuvvetler ayrılığı', ['Kuvvetler birliği', 'Merkeziyetçi vesayet sistemi', 'İdari özerklik doktrini'], 'Montesquieu tarafından kuramsallaştırılan kuvvetler ayrılığı, iktidarın tek elde toplanarak özgürlükleri tehdit etmesini önlemeyi amaçlar.'),
  ('Bir hukuk devletinde temel hak ve özgürlüklerin sınırlandırılmasında "ölçülülük ilkesi" hangi üç alt ölçütten oluşur?', 'Elverişlilik, gereklilik ve orantılılık', ['Genellik, soyutluk ve süreklilik', 'Aleniyet, açıklık ve tarafsızlık', 'Eşitlik, özgürlük ve dayanışma'], 'Ölçülülük ilkesi gereği sınırlama aracı amaca ulaşmaya elverişli olmalı, en hafif müdahale aracı seçilmeli ve sınırlama ile amaç arasında makul bir denge bulunmalıdır.'),
  ('Kanunların Anayasaya uygunluğunu denetleyen anayasa yargısı mekanizmasında, bireylerin temel haklarının kamu gücü tarafından ihlal edildiği iddiasıyla olağan kanun yollarını tükettikten sonra başvurabildikleri yol hangisidir?', 'Anayasa Mahkemesine bireysel başvuru', ['Yasama organına kanun teklifi sunma', 'Bakanlar Kurulundan idari af isteme', 'Yargıtay Cumhuriyet Başsavcılığına şikayet'], 'Bireysel başvuru yolu, iç hukukta anayasal hak ihlallerinin giderilmesini sağlayarak hakların etkin korunmasına hizmet eder.'),
  ('İngiltere\'de 1679 yılında kabul edilerek keyfi tutuklamaları önleyen ve tutuklanan kişinin kısa sürede hakim önüne çıkarılmasını güvence altına alan yasa hangisidir?', 'Habeas Corpus Yasası', ['Haklar Dilekçesi Yasası', 'Soyluluk ve Temsil Fermanı', 'Kıta Ablukası Kararnamesi'], 'Habeas Corpus (bedenine sahip ol), tutuklamanın hukuka uygunluğunun bağımsız bir yargıç tarafından denetlenmesi güvencesinin tarihsel temelini oluşturur.'),
  ('İngiltere\'de 1689 Şanlı Devrim sonrasında kabul edilerek parlamentonun onayını almadan kralın kanunları askıya almasını ve vergi toplamasını yasaklayan belge hangisidir?', 'İngiliz Haklar Bildirgesi', ['Magna Carta Libertatum', 'Nantes Hoşgörü Fermanı', 'Augsburg Barış Antlaşması'], '1689 Haklar Bildirgesi, meşruti monarşinin ve parlamenter üstünlüğün temellerini atarak ifade özgürlüğü ve adil yargılanma güvenceleri getirmiştir.'),
  ('1776 yılında Kuzey Amerika\'da kabul edilerek insanların doğuştan özgür ve bağımsız olduğunu, yaşam, özgürlük ve mutluluğu arama haklarına sahip bulunduğunu ilan eden ilk modern haklar bildirgesi hangisidir?', 'Virginia Haklar Bildirgesi', ['Magna Carta Libertatum', 'Avrupa İnsan Hakları Sözleşmesi', 'Birleşmiş Milletler Antlaşması'], 'George Mason tarafından kaleme alınan Virginia Haklar Bildirgesi, Amerikan Bağımsızlık Bildirgesi\'ne ve 1789 Fransız Bildirisi\'ne doğrudan esin kaynağı olmuştur.'),
  ('İnsan hakları literatüründe yaşam hakkı, kişi özgürlüğü, düşünce özgürlüğü ve seçme seçilme hakkı gibi devletten daha çok müdahale etmemesini veya siyasi katılımı sağlamasını bekleyen haklar hangi kuşak haklar olarak sınıflandırılır?', 'Birinci kuşak haklar', ['İkinci kuşak haklar', 'Üçüncü kuşak haklar', 'Dördüncü kuşak haklar'], 'Karel Vasak\'ın sınıflandırmasına göre birinci kuşak haklar, klasik medeni ve siyasi hakları kapsayan özgürlük ve katılım haklarıdır.'),
  ('Çalışma hakkı, sosyal güvenlik hakkı, eğitim hakkı ve sağlık hakkı gibi devletin aktif edimde bulunarak toplumsal refahı sağlamasını gerektiren haklar hangi kuşak haklar kapsamında değerlendirilir?', 'İkinci kuşak haklar', ['Birinci kuşak haklar', 'Üçüncü kuşak haklar', 'Sadece özel hukuk hakları'], 'İkinci kuşak haklar, ekonomik, sosyal ve kültürel hakları kapsar ve devletin eşit fırsatlar yaratmak için pozitif yükümlülük üstlenmesini gerektirir.'),
  ('Barış hakkı, sağlıklı bir çevrede yaşama hakkı ve insanlığın ortak mirasından yararlanma hakkı gibi kolektif nitelikli haklar insan hakları öğretisinde hangi grupta yer alır?', 'Üçüncü kuşak (dayanışma) hakları', ['Birinci kuşak (kişi) hakları', 'İkinci kuşak (ekonomik) hakları', 'Yalnızca yerel yönetim hakları'], 'Üçüncü kuşak haklar, tek bir devletin çabasıyla değil uluslararası iş birliği ve toplumsal dayanışmayla gerçekleştirilebilen kolektif haklardır.'),
  ('Medeni hukukta bir kişinin haklarını kullanırken ve borçlarını yerine getirirken uyması gereken, makul ve dürüst bir insandan beklenen objektif davranış ölçütüne ne ad verilir?', 'Dürüstlük kuralı', ['Sübjektif iyi niyet ilkesi', 'Kanun boşluğu doldurma yetkisi', 'Kusursuz sorumluluk karinesi'], 'Medeni Kanun\'un 2. maddesindeki dürüstlük kuralı (objektif iyi niyet), hakların açıkça kötüye kullanılmasını hukuk düzeninin korumayacağını belirtir.'),
  ('Medeni hukukta bir hakkın kazanılmasında o hakkın kazanılmasına engel bir durumun varlığını gerekli özeni göstermesine rağmen bilmeme hâli hangi kavramla ifade edilir?', 'İyi niyet', ['Dürüstlük kuralı', 'Ağır ihmal sorumluluğu', 'Sözleşme serbestisi ilkesi'], 'Sübjektif iyi niyet, hakkın kazanılmasında rol oynayan mazur görülebilir bilgisizlik hâlidir; örneğin emin sıfatıyla zilyetten mal satın alan iyi niyetli üçüncü kişi korunur.'),
  ('Birleşmiş Milletler Çocuk Hakları Sözleşmesi\'nin tüm maddelerinin yorumlanmasında ve çocuğu ilgilendiren her türlü yargısal veya idari kararda öncelikli ölçüt olarak kabul edilen temel ilke nedir?', 'Çocuğun yüksek yararı ilkesi', ['Ebeveynin mutlak otoritesi ilkesi', 'İdarenin ekonomik tasarruf ilkesi', 'Ceza yaptırımlarının ağırlığı ilkesi'], 'Çocuk Hakları Sözleşmesi madde 3 uyarınca kamusal ya da özel sosyal yardım kuruluşları, mahkemeler ve yasama organları çocuğu ilgilendiren tüm faaliyetlerde çocuğun yüksek yararını temel düşünce olarak gözetir.'),
  ('AİHS madde 10\'da düzenlenen ifade özgürlüğünün demokratik bir toplumda yalnızca hoş karşılanan görüşleri değil, "devleti veya toplumun bir kesimini inciten, şoke eden veya rahatsız eden" düşünceleri de korumasının temel nedeni nedir?', 'Çoğulculuk, hoşgörü ve açık fikirlilik olmaksızın demokratik bir toplumun var olamayacağı anlayışı', ['İfade özgürlüğünün hiçbir durumda sınırlandırılamayan mutlak bir hak kabul edilmesi', 'Basın kuruluşlarının özel hukuk tazminat sorumluluğundan tamamen muaf tutulması', 'Siyasi eleştirilerin yalnızca parlamento kürsüsünde serbest bırakılmak istenmesi'], 'AİHM\'nin Handyside içtihadında vurguladığı gibi ifade özgürlüğü çoğulcu demokrasinin temelidir; ancak nefret söylemi ve şiddete teşvik bu korumanın dışındadır.'),
  ('CEDAW sözleşmesinin 4. maddesinde öngörülen "geçici özel önlemler" (pozitif ayrımcılık uygulamaları) neden sözleşme kapsamında ayrımcılık sayılmaz?', 'Kadınlarla erkekler arasındaki fiili eşitsizliği hızla gidermeyi amaçladığı ve fırsat eşitliği sağlandığında sona ereceği için', ['Yalnızca özel sektör kuruluşları tarafından gönüllü olarak uygulanabildiği için', 'Erkeklerin seçme ve seçilme haklarını kalıcı olarak ortadan kaldırdığı için', 'Uluslararası sözleşmelerde eşitlik ilkesine hiçbir hukuki bağlayıcılık tanınmadığı için'], 'CEDAW, yalnızca kağıt üzerindeki hukuki eşitliği değil fiili eşitliği hedefler; bu nedenle kadınların temsilini veya eğitime erişimini artıran geçici destek politikalarını meşru görür.'),
  ('CEDAW sözleşmesinin uygulanmasını izleyen ve taraf devletlerin periyodik raporlarını inceleyen uluslararası denetim organı hangisidir?', 'Kadınlara Karşı Ayrımcılığın Önlenmesi Komitesi', ['Avrupa İnsan Hakları Mahkemesi Büyük Dairesi', 'Uluslararası Adalet Divanı Genel Sekreterliği', 'Birleşmiş Milletler Ekonomik Kalkınma Konseyi'], 'CEDAW Komitesi, bağımsız uzmanlardan oluşur; taraf devletlerin sunduğu raporları değerlendirir ve İhtiyari Protokol\'e taraf devletler bakımından bireysel başvuruları inceleyebilir.'),
  ('Çocuk Hakları Sözleşmesi\'nde yer alan dört temel ilke (yaşama ve gelişme, ayrımcılık yasağı, çocuğun yüksek yararı ve katılım hakkı) içinde "katılım hakkı" neyi ifade eder?', 'Görüş oluşturma yeteneğine sahip çocuğun kendisini ilgilendiren her konuda görüşlerini serbestçe ifade etmesi ve bu görüşlere yaşı ile olgunluğuna göre önem verilmesi', ['On sekiz yaşından küçük tüm çocukların genel seçimlerde milletvekili adayı olabilmesi', 'Çocukların velilerinin izni olmaksızın tam zamanlı ağır sanayi işlerinde çalışabilmesi', 'Çocukların kendi okul müfredatlarını öğretmenlerden bağımsız olarak tek başlarına belirlemesi'], 'Sözleşmenin 12. maddesi, çocuğun sadece korunan pasif bir nesne değil, kendi yaşamını etkileyen kararlarda dinlenmesi gereken bir hak öznesi olduğunu kabul eder.'),
  ('1949 tarihli dört Cenevre Sözleşmesi\'nden özellikle Dördüncü Cenevre Sözleşmesi hangi grubun korunmasına odaklanır?', 'Savaş zamanında sivil kişilerin korunması', ['Karada silahlı kuvvetlerin yaralı ve hastalarının korunması', 'Denizde silahlı kuvvetlerin yaralı ve kazazedelerinin korunması', 'Savaş esirlerine uygulanacak muamele standartları'], 'İlk üç Cenevre Sözleşmesi sırasıyla karadaki yaralıları, denizdeki yaralıları ve savaş esirlerini düzenlerken, Dördüncü Cenevre Sözleşmesi işgal altındaki ve çatışma bölgelerindeki sivilleri korur.'),
  ('Uluslararası insancıl hukukta (Cenevre Sözleşmeleri ve Ek Protokoller) silahlı çatışma taraflarına yüklenen "ayrım gözetme ilkesi" (principle of distinction) hangi zorunluluğu getirir?', 'Saldırıların yalnızca askeri hedeflere yöneltilmesi, sivillerin ve sivil yerleşim yerlerinin kesinlikle hedef alınmaması', ['Çatışmada yalnızca geleneksel kara birliklerinin kullanılması ve hava araçlarının yasaklanması', 'Savaş esirlerinin rütbelerine göre farklı ülkelere gönderilmesi', 'Tarafsız ülkelerin savaşan taraflara eşit miktarda silah yardımı yapması'], 'Ayrım gözetme ilkesi uluslararası insancıl hukukun temel taşıdır; siviller, hastaneler, okullar ve kültürel miras alanları askeri hedef haline getirilemez.'),
  ('Uluslararası insan hakları hukukunda "geri göndermeme ilkesi" (non-refoulement) devletlere hangi yasağı getirir?', 'Bir kişiyi yaşamının, özgürlüğünün veya işkence görmeme hakkının ciddi tehlike altında olacağı bir ülkeye sınır dışı etmeme veya iade etmeme', ['Bir yabancının turistik vizesi dolduğunda ülkesine dönmesine kesinlikle izin vermeme', 'Suç işleyen kendi vatandaşlarını ulusal mahkemelerde yargılamaktan vazgeçme', 'Uluslararası ticarette ithal edilen kusurlu malları üretici ülkeye iade etmeme'], 'Geri göndermeme ilkesi, 1951 Mülteci Sözleşmesi, İşkenceye Karşı Sözleşme ve AİHM içtihatlarıyla pekişmiş olup kişinin zulüm veya işkence riski taşıyan ülkeye gönderilmesini yasaklar.'),
  ('Birleşmiş Milletler sisteminde 1984 yılında kabul edilen "İşkenceye ve Diğer Zalimane, İnsanlık Dışı veya Küçültücü Muamele veya Cezaya Karşı Sözleşme" devletlere hangi pozitif yükümlülüğü de getirir?', 'İşkence iddialarını derhal, tarafsız ve etkili biçimde soruşturmak, failleri yargılamak ve mağdurların tazminat ile rehabilitasyon hakkını sağlamak', ['Yalnızca uluslararası çatışmalarda işkenceyi yasaklayıp iç hukuk soruşturmalarını kapsam dışı bırakmak', 'İşkence ile elde edilen itirafları yalnızca ağır terör davalarında yardımcı delil saymak', 'İşkence suçlarında faillerin amirlerinin emriyle hareket etmesini geçerli bir hukuka uygunluk nedeni kabul etmek'], 'Sözleşme, amir emrinin veya olağanüstü hâlin işkenceye gerekçe olamayacağını, işkenceyle alınan beyanların delil sayılamayacağını ve faillerin cezasız bırakılamayacağını hükme bağlar.'),
  ('Bir devletin uluslararası bir insan hakları sözleşmesini "imzalaması" ile "onaylaması" (taraf olması) arasındaki hukuki fark nedir?', 'İmza devletin sözleşmenin amaç ve konusuna aykırı davranmama niyetini gösterirken, onaylama sözleşmenin devlet bakımından hukuken bağlayıcı hâle gelmesini sağlar', ['İmza sözleşmeyi doğrudan anayasa maddesi hâline getirirken, onaylama yalnızca sembolik bir törendir', 'Onaylama işlemi yalnızca yürütme organının sözlü açıklamasıyla tamamlanır, imza ise parlamento oylaması gerektirir', 'Bir sözleşmeyi imzalayan devlet, onaylamasa bile her yıl uluslararası mahkemeye zorunlu tazminat öder'], 'Viyana Antlaşmalar Hukuku Sözleşmesi uyarınca çoğu çok taraflı antlaşmada bağlayıcılık, devletin iç hukuk usullerini (genellikle parlamento onayı) tamamlayıp onay belgesini tevdi etmesiyle doğar.'),
  ('Uluslararası sözleşmelerde bir devletin antlaşmaya taraf olurken belirli bir maddenin kendisi bakımından hukuki etkisini hariç tutmak veya değiştirmek amacıyla yaptığı tek taraflı beyana ne ad verilir?', 'Çekince', ['İhtiyari protokol', 'Yürütmeyi durdurma', 'Diplomatik nota'], 'Çekince, sözleşmenin konu ve amacına aykırı olmamak ve sözleşme tarafından yasaklanmamak kaydıyla devletlerin belirli hükümlere ilişkin kapsam sınırlaması yapmasına olanak tanır.'),
  ('AİHS\'in 5. maddesinde düzenlenen "özgürlük ve güvenlik hakkı" kapsamında yakalanan veya tutuklanan bir kişiye tanınan temel güvencelerden biri hangisidir?', 'Yakalanma nedenlerinin ve hakkındaki suçlamaların anladığı bir dilde derhal bildirilmesi ve en kısa sürede hakim önüne çıkarılması', ['Soruşturma tamamlanıncaya kadar yakınlarıyla iletişim kurmasının süresiz olarak engellenmesi', 'Hakim kararı olmadan güvenlik güçlerince en az otuz gün gözaltında tutulabilmesi', 'Yalnızca maddi gücü varsa tutukluluğa itiraz başvurusunda bulunabilmesi'], 'AİHS madde 5, keyfi özgürlük kısıtlamalarını önlemek için yakalama sebeplerinin derhal bildirilmesini, hızlı yargısal denetimi ve haksız tutuklama hâlinde tazminat hakkını güvence altına alır.'),
  ('İnsan hakları hukukunda devletin bireylerin haklarına keyfi biçimde müdahale etmemesi "negatif yükümlülük" olarak adlandırılırken, "pozitif yükümlülük" neyi ifade eder?', 'Devletin bireylerin haklarını üçüncü kişilerin ihlallerine karşı korumak ve hakların fiilen kullanılmasını sağlamak için aktif önlemler alması', ['Devletin yalnızca ekonomik kriz dönemlerinde vergi oranlarını artırma yetkisi kullanması', 'Devletin uluslararası mahkemelerdeki tüm savunmalarında mutlaka ihlali kabul etmesi', 'Devletin vatandaşlarına yalnızca belirli siyasi görüşleri ifade etme izni vermesi'], 'Örneğin yaşam hakkı bağlamında devletin hem kendi görevlilerinin hukuksuz güç kullanmasını önlemesi (negatif) hem de aile içi şiddet veya tehlikeli tesis risklerine karşı koruyucu önlem alması (pozitif) gerekir.'),
  ('Birleşmiş Milletler sisteminde 2006 yılında kabul edilerek engelli bireylerin toplumun tüm alanlarına tam ve etkin katılımını, erişilebilirlik ve makul düzenleme haklarını güvenceye alan sözleşme hangisidir?', 'Engellilerin Haklarına İlişkin Sözleşme', ['Çocuk Hakları Sözleşmesi', 'Irk Ayrımcılığının Ortadan Kaldırılması Sözleşmesi', 'Göçmen İşçilerin Haklarının Korunması Sözleşmesi'], 'BM Engellilerin Haklarına İlişkin Sözleşme, engelliliği tıbbi bir yardım meselesi olmaktan çıkarıp insan hakları ve eşit erişim temelinde tanımlayan dönüm noktası bir belgedir.'),
  ('Bir belediye meclisinin, engelli yurttaşların toplu taşıma araçlarına erişimini kolaylaştırmak için rampalı otobüs zorunluluğu getirmesi hangi insan hakları kavramının somut uygulamasıdır?', 'Makul düzenleme ve erişilebilirlik yükümlülüğü', ['Cezaların şahsiliği ve kanunilik ilkesi', 'Sözleşme serbestisi ve şekil özgürlüğü', 'Kuvvetler ayrılığı ve yargı dokunulmazlığı'], 'Erişilebilirlik ve makul düzenleme, engelli bireylerin diğer bireylerle eşit koşullarda toplumsal yaşama katılabilmesi için fiziksel çevre ve hizmetlerde gerekli uyarlamaların yapılmasını ifade eder.'),
  ('Hukukta "tüzel kişi" kavramı aşağıdakilerden hangisini ifade eder?', 'Belirli bir amacı gerçekleştirmek üzere bir araya gelmiş kişi veya mal topluluklarına hukuk düzenince tanınan bağımsız hak ve borç ehliyeti', ['Yalnızca devlet memurluğu sınavını kazanmış gerçek kişilerin sahip olduğu statü', 'On sekiz yaşını doldurmuş tüm gerçek kişilerin oy kullanma ehliyeti', 'Mahkeme salonunda hakim ve savcılara verilen resmi protokol unvanı'], 'Dernekler, vakıflar, ticaret şirketleri, belediyeler ve üniversiteler gibi tüzel kişiler, kendilerini oluşturan insanlardan bağımsız hukuki varlığa ve mal varlığına sahiptir.'),
  ('Özel hukuk tüzel kişileri olan "dernek" ile "vakıf" arasındaki en temel yapısal fark nedir?', 'Dernek belirli bir ortak amaç için bir araya gelen kişi topluluğu iken, vakıf belirli ve sürekli bir amaca özgülenmiş mal topluluğudur', ['Dernek yalnızca kazanç paylaşmak için kurulurken, vakıf sadece devlet bütçesiyle kurulur', 'Vakıfların tüzel kişiliği yokken, dernekler kamu tüzel kişisi statüsündedir', 'Dernekler yalnızca uluslararası alanda faaliyet gösterirken, vakıflar sadece aile içi miras paylaşımı yapar'], 'Medeni Kanun\'a göre dernekler en az yedi gerçek veya tüzel kişinin birleşmesiyle oluşan kişi topluluğu, vakıflar ise belirli bir mal varlığının sürekli bir amaca tahsis edilmesiyle kurulan mal topluluğudur.'),
  ('Kamu hukukunda idarenin tek yanlı iradesiyle bir taşınmazın mülkiyetini kamu yararı amacıyla ve gerçek karşılığını peşin ödemek koşuluyla özel mülkiyetten kamu mülkiyetine geçirmesi işlemine ne ad verilir?', 'Kamulaştırma', ['Devletleştirme', 'Geçici işgal', 'İdari haciz'], 'Kamulaştırma (istimlak), örneğin yol, okul veya hastane yapımı gibi kamu yararı gerektiren hâllerde özel mülkiyetteki taşınmazların bedeli ödenerek idarece devralınmasıdır.'),
  ('Ceza hukukunda "zamanaşımı" kurumunun hukuk düzeninde kabul edilmesinin başlıca gerekçesi nedir?', 'Uzun zaman geçmesiyle delillerin kaybolması, toplumsal tepkinin zayıflaması ve kişinin ömür boyu ceza tehdidi altında bırakılmaması', ['Ceza mahkemelerinin çalışma saatlerinin yalnızca belirli aylarla sınırlandırılması', 'Mağdurun şikayet hakkını kullanmak istememesi hâlinde savcının yetkisiz kalması', 'Yalnızca mali nitelikli suçlarda hazinenin gelir kaybını önlemek istenmesi'], 'Dava veya ceza zamanaşımı hukuki barışı ve yargılamada delil güvenilirliğini gözetir; ancak soykırım ve insanlığa karşı suçlar gibi en ağır uluslararası suçlarda zamanaşımı işlemez.'),
  ('İş hukukunda işverenin haklı bir neden olmaksızın belirsiz süreli iş sözleşmesini sona erdirmek istemesi durumunda işçiye çalışma süresine göre önceden bildirimde bulunması veya bunun ücretini ödemesi hangi yükümlülüktür?', 'İhbar öneli (bildirim süresi) ve ihbar tazminatı', ['Yıllık ücretli izin alacağı', 'Fazla mesai zammı ödemesi', 'Hafta tatili dinlenme hakkı'], 'İhbar süresi, hem işçinin yeni iş bulabilmesi hem de işçinin ayrılması durumunda işverenin yeni çalışan bulabilmesi için iki taraflı olarak tanınmış bir geçiş güvencesidir.'),
  ('Aile hukukunda eşlerin evlilik birliği içinde edindikleri malların boşanma hâlinde kural olarak nasıl paylaşılacağını düzenleyen Türk Medeni Kanunu\'ndaki yasal mal rejimi hangisidir?', 'Edinilmiş mallara katılma rejimi', ['Tam mal ayrılığı rejimi', 'Kişisel malların devri rejimi', 'Kıdem esasına dayalı miras rejimi'], '2002 yılında yürürlüğe giren Türk Medeni Kanunu, eşler başka bir mal rejimi sözleşmesi seçmedikçe evlilik süresince karşılığı verilerek edinilen malların eşit paylaşımına dayanan edinilmiş mallara katılma rejimini yasal rejim kabul etmiştir.'),
  ('Ticaret hukukunda bir tacirin ekonomik durumunun bozulması nedeniyle borçlarını ödeyemez hâle gelmesi ve mahkeme kararıyla tüm mal varlığının alacaklıları arasında paylaştırılması sürecine ne ad verilir?', 'İflas', ['İhtiyati haciz', 'Temlik işlemi', 'Takas ve mahsup'], 'İflas, kural olarak tacirler hakkında uygulanan ve borçlunun tüm haczedilebilir mal varlığının bütün alacaklıların eşit tatmini için tasfiye edildiği külli icra yoludur.'),
  ('Tüketici hukukunda satıcının tüketiciye teslim ettiği malın sözleşmede kararlaştırılan niteliklere veya standartlara uymaması durumuna ne ad verilir?', 'Ayıplı mal', ['Muvazaalı işlem', 'Sebepsiz iktisap', 'Haksız rekabet'], 'Ayıplı mal durumunda tüketici; bedel iadesi, ayıp oranında indirim, ücretsiz onarım veya malın ayıpsız misli ile değiştirilmesi seçimlik haklarından birini kullanabilir.'),
  ('Anayasa hukukunda milletvekillerinin meclis çalışmalarındaki oy ve sözlerinden, ileri sürdükleri düşüncelerden dolayı ömür boyu sorumlu tutulamamasına ne ad verilir?', 'Yasama sorumsuzluğu', ['Yasama dokunulmazlığı', 'Yürütme ayrıcalığı', 'İdari takdir yetkisi'], 'Yasama sorumsuzluğu (kürsü dokunulmazlığı) mutlaktır, kaldırılamaz ve milletvekilliği sona erdikten sonra da devam eder; yasama dokunulmazlığı ise geçicidir ve meclis kararıyla kaldırılabilir.'),
  ('Yargı örgütünde ilk derece mahkemesinin verdiği kararın hem maddi vakıalar hem de hukuka uygunluk yönünden bir üst mahkemece yeniden incelenmesini sağlayan olağan kanun yolu hangisidir?', 'İstinaf', ['Yargılamanın iadesi', 'Kanun yararına bozma', 'Olağanüstü itiraz'], 'Türk yargı sisteminde Bölge Adliye ve Bölge İdare Mahkemelerince yürütülen istinaf aşaması, ilk derece ile Yargıtay/Danıştay temyiz denetimi arasında yer alan ikinci derece kanun yoludur.'),
  ('Hukukta "hakkın kötüye kullanılması yasağı" aşağıdakilerden hangisini ifade eder?', 'Bir kimsenin hukuken sahip olduğu bir hakkı, kendi meşru çıkarından ziyade başkasına zarar vermek amacıyla açıkça dürüstlük kuralına aykırı kullanmasının hukukça korunmaması', ['Bir kişinin kendi mülkiyetindeki malı hiçbir koşulda satamaması veya bağışlayamaması', 'Sözleşme taraflarından birinin ekonomik zorluğa düşmesi hâlinde tüm borçlarının otomatik silinmesi', 'İdari kurumların kamu hizmeti sunarken vatandaşlardan harç ve resim talep edememesi'], 'Örneğin kendi arazisine hiçbir yarar sağlamadığı hâlde yalnızca komşusunun manzarasını ve güneşini kesmek için yüksek duvar örmek hakkın kötüye kullanılmasına klasik bir örnektir.'),
  ('İnsan hakları belgelerinin tarihsel gelişiminde 1945 yılında kabul edilen Birleşmiş Milletler Antlaşması\'nın temel önemi nedir?', 'İnsan haklarının korunmasını ilk kez yalnızca devletlerin iç işi olmaktan çıkarıp uluslararası barış ve iş birliğinin ortak konusu hâline getirmesi', ['Bütün üye devletlerin ulusal parlamentolarını feshederek tek dünya hükümeti kurması', 'Uluslararası hukukta devlet egemenliği ilkesini tamamen ortadan kaldırması', 'Sadece Avrupa kıtasındaki savaş zararlarının tazminini düzenlemesi'], 'BM Antlaşması, insan haklarına saygıyı örgütün temel amaçları arasına alarak İHEB ve sonraki tüm BM insan hakları sözleşmelerinin anayasal zeminini hazırlamıştır.'),
  ('Bir sanık hakkında beraat ya da mahkumiyet kararını vermeye yetecek kesin ve inandırıcı delil elde edilemediğinde sanık lehine karar verilmesini öngören ilke hangisidir?', 'Şüpheden sanık yararlanır', ['İddia eden iddiasını kanıtlar', 'Hukuka aykırı delil yasaktır', 'Kıyas yasağı kesin kuraldır'], 'Latince "in dubio pro reo" olarak bilinen bu ilke, masumiyet karinesinin doğrudan sonucu olup kuşku halinde mahkumiyet verilmesini engeller.'),
  ('Kanunda suç sayılmayan bir fiili, benzer bir suç maddesine benzeterek hakim tarafından cezalandırmaya çalışmak hangi ceza hukuku yasağına aykırıdır?', 'Kıyas yasağı', ['Çifte yargılama yasağı', 'Geriye yürüme yasağı', 'Keyfi tutuklama yasağı'], 'Suçta ve cezada kanunilik ilkesinin alt unsuru olan kıyas yasağı, ceza hukukunda kıyas yoluyla yeni suç ve ceza yaratılmasını yasaklar.'),
  ('Bir fiilin işlendiği tarihten sonra yürürlüğe giren yeni ceza kanunu, önceki kanuna göre sanığın cezası bakımından daha hafif yaptırım öngörüyorsa hakim nasıl davranır?', 'Lehe olan yeni kanunu uygular', ['Suç tarihindeki eski kanunu uygular', 'İki kanunun ceza ortalamasını uygular', 'Dosyayı Anayasa Mahkemesine gönderir'], 'Geriye yürümezlik ilkesinin istisnası olarak lehe ceza kanunu geçmişe yürür ve sanık yararına olan düzenleme uygulanır.'),
  ('Ceza yargılamasında kesinleşmiş bir hükümle sonuçlanmış aynı fiilden dolayı kişinin ikinci kez yargılanıp cezalandırılamamasını ifade eden ilke hangisidir?', 'Ne bis in idem ilkesi', ['Pacta sunt servanda ilkesi', 'Nulla poena sine lege ilkesi', 'Audiatur et altera pars ilkesi'], '"Ne bis in idem" (aynı fiilden iki kez yargılama olmaz) ilkesi, hukuki güvenliği ve adil yargılanmayı korumak için çifte yargılamayı yasaklar.'),
  ('Yargılamada iddia makamı ile savunma makamının delil sunma, tanık dinletme ve görüş bildirme bakımından dengeli imkanlara sahip olmasını ifade eden ilke hangisidir?', 'Silahların eşitliği', ['Doğrudan doğruyalık ilkesi', 'Davasız yargılama olmaz ilkesi', 'Yargılamanın kesintisizliği kuralı'], 'Silahların eşitliği, taraflardan birinin diğerine göre dezavantajlı konuma düşmeden iddialarını mahkeme önünde ileri sürebilmesini güvence altına alır.'),
  ('Hakimlerin azledilememesi, kendileri istemedikçe erken emekliye ayrılamaması ve mali haklarından yoksun bırakılamaması hangi anayasal kavramla ifade edilir?', 'Hakimlik teminatı', ['Yasama sorumsuzluğu', 'Yargısal dokunulmazlık', 'İdari yetki genişliği'], 'Hakimlik teminatı, yargı bağımsızlığının somut güvencesi olup hakimlerin baskı ve görevden alınma kaygısı olmadan karar vermesini sağlar.'),
  ('Bir bakanlığın çıkardığı yönetmelik hükmü, Türkiye Büyük Millet Meclisinin kabul ettiği bir kanunun açık emrine aykırıysa normlar hiyerarşisine göre hangi sonuç doğar?', 'Kanun hükmü üstün tutulur', ['Yönetmelik sonradan çıktığı için uygulanır', 'İki norm idari genelgeyle birleştirilir', 'Yönetmelik kanunu kendiliğinden yürürlükten kaldırır'], 'Normlar hiyerarşisinde kanun yönetmelikten üstündür; alt norm üst norma aykırı olamayacağı için kanun esas alınır ve yönetmelik iptal edilebilir.'),
  ('Türkiye\'de normlar hiyerarşisinde usulüne göre yürürlüğe konulmuş temel hak ve özgürlüklere ilişkin milletlerarası antlaşmalar ile kanunlar aynı konuda farklı hükümler içerirse hangisi esas alınır?', 'Milletlerarası antlaşma hükümleri', ['Sonradan yürürlüğe giren kanun hükümleri', 'Cumhurbaşkanlığı kararnamesi hükümleri', 'Danıştayın istişari karar hükümleri'], 'Anayasa\'nın 90. maddesi uyarınca temel hak ve özgürlüklere ilişkin uluslararası antlaşmalarla kanunlar çatıştığında antlaşma hükümleri üstün tutulur.'),
  ('Hukuka aykırı yöntemlerle, örneğin izinsiz dinleme veya baskı altında elde edilen bulguların mahkemede hükme esas alınamaması hangi yargı ilkesinin sonucudur?', 'Yasak delil ilkesi', ['Resen araştırma ilkesi', 'Serbest delil değerlendirmesi', 'Teksif ve çabukluk ilkesi'], 'Hukuka aykırı elde edilmiş bulgular delil olarak kabul edilemez; bu kural insan haklarının ve adil yargılanmanın ihlalini önler.'),
  ('İdari bir kurumun bir memura verdiği disiplin cezasının iptali için açılacak dava, Türkiye\'deki yargı sisteminde hangi yargı kolunda görülür?', 'İdari yargı', ['Adli yargı', 'Anayasa yargısı', 'Hesap yargısı'], 'İdarenin kamu gücünü kullanarak tesis ettiği tek yanlı idari işlemlerin hukuka uygunluk denetimi idari yargıda yapılır.'),
  ('İki vatandaş arasında kira sözleşmesinden doğan tahliye ve alacak uyuşmazlığı, Türkiye\'deki yargı teşkilatında hangi yargı kolunun görev alanına girer?', 'Adli yargı', ['İdari yargı', 'Uyuşmazlık yargısı', 'Anayasa yargısı'], 'Özel hukuk kişileri arasındaki sözleşmelerden doğan hukuk uyuşmazlıkları adli yargı içindeki hukuk mahkemelerinde çözümlenir.'),
  ('1982 Anayasası\'na göre olağan dönem Cumhurbaşkanlığı kararnameleriyle hangi hak kategorisi kural olarak düzenlenemez?', 'Kişi hakları ve siyasi haklar', ['Bakanlıkların kuruluş ve görev esasları', 'Üst kademe kamu yöneticilerinin atanması', 'Devlet Denetleme Kurulunun işleyişi'], 'Anayasa\'nın 104. maddesine göre temel haklar, kişi hakları ve ödevleri ile siyasi haklar ve ödevler olağan Cumhurbaşkanlığı kararnamesiyle düzenlenemez.'),
  ('Anayasa Mahkemesine yapılan bireysel başvuru yolunun tüketilmesinden önce başvurucunun yerine getirmesi gereken zorunlu usul şartı nedir?', 'Olağan kanun yollarının tüketilmesi', ['Meclis dilekçe komisyonuna başvurulması', 'Avrupa İnsan Hakları Mahkemesine gidilmesi', 'Kamu Başdenetçisinden onay belgesi alınması'], 'Anayasa Mahkemesine bireysel başvuru ikincil niteliktedir; bu nedenle idari ve yargısal olağan başvuru yollarının önceden tüketilmesi şarttır.'),
  ('Türkiye\'de Anayasa Mahkemesine bireysel başvuru hakkı hangi yıldaki anayasa değişikliği ile hukuk sistemine girmiştir?', '2010', ['1982', '1995', '2001'], 'Anayasa Mahkemesine bireysel başvuru mekanizması 2010 anayasa değişikliğiyle kabul edilmiş ve 2012 yılında fiilen uygulanmaya başlanmıştır.'),
  ('Bir hakimin, davacı veya davalıyla yakın akrabalık ilişkisi bulunması durumunda davaya bakmaktan çekinmesi hangi adil yargılanma unsurunu korur?', 'Tarafsız mahkeme güvencesi', ['Makul sürede yargılanma hakkı', 'Kararların gerekçeli olması ilkesi', 'Kanun yoluna başvuru serbestisi'], 'Tarafsızlık, hakimin taraflara eşit mesafede durmasını ve kişisel önyargı ya da çıkar çatışması olmaksızın hüküm kurmasını gerektirir.'),
  ('Mahkemelerin verdikleri tüm kararları hukuki ve olgusal dayanaklarıyla yazılı biçimde açıklamak zorunda olması hangi yargı ilkesidir?', 'Gerekçeli karar hakkı', ['Tasarruf ve iddia ilkesi', 'Sözlü yargılama temel ilkesi', 'Yargılamanın aleniliği kuralı'], 'Anayasa gereği bütün mahkeme kararları gerekçeli yazılır; bu sayede taraflar kararın keyfi olmadığını denetleyebilir ve üst mahkemeye itiraz edebilir.'),
  ('Yargılamanın gereksiz gecikmelere yol açmadan, uyuşmazlığın niteliğine uygun bir zaman diliminde sonuçlandırılmasını öngören ilke hangisidir?', 'Makul sürede yargılanma hakkı', ['Doğal yargıç ve yetki güvencesi', 'Cezanın bireyselleştirilmesi kuralı', 'Hukuki dinlenilme temel hakkı'], 'Makul sürede yargılanma hakkı, "geciken adalet adalet değildir" anlayışıyla bireylerin belirsizlik içinde uzun süre bırakılmasını önler.'),
  ('Bir devletin kamu düzenini koruma amacıyla temel hak ve özgürlükleri sınırlandırırken seçilen aracın amaca elverişli, gerekli ve orantılı olmasını arayan anayasal ölçüt hangisidir?', 'Ölçülülük ilkesi', ['İdari istikrar ilkesi', 'Yasamanın genelliği ilkesi', 'Hukuki eşitlik ilkesi'], 'Ölçülülük ilkesi; elverişlilik, gereklilik ve orantılılık alt unsurlarıyla hak sınırlamalarının gereğinden ağır olmasını engeller.'),
  ('Temel hak ve özgürlüklerin kanunla sınırlandırılması sırasında dahi dokunulamayacak, hakkı kullanılamaz hale getiremeyecek çekirdek alanı koruyan ölçüt hangisidir?', 'Hakkın özüne dokunma yasağı', ['Kuvvetler ayrılığı mekanizması', 'Yönetimin bütünlüğü temel ilkesi', 'Yasama yetkisinin devredilmezliği'], 'Bir temel hakkın özüne dokunulması, o hakkın varlık nedenini ortadan kaldıracak kadar ağır biçimde kısıtlanması anlamına gelir ve Anayasa\'ca yasaktır.'),
  ('Bir kişi hakkında polis tarafından yakalama yapıldığında, kişinin suçlamayı anlamadığı bir dilde sorgulanmayıp ücretsiz tercüman yardımından yararlanması hangi hakkın parçasıdır?', 'Adil yargılanma hakkı', ['Seyahat ve yerleşme hakkı', 'Seçme ve seçilme hakkı', 'Çalışma ve sözleşme hakkı'], 'Adil yargılanma hakkı kapsamında kişi, kendisine yöneltilen suçlamanın niteliğini ve nedenini anladığı bir dilde öğrenme ve tercüman desteğinden yararlanma hakkına sahiptir.'),
  ('Yasama organının, anayasa ile çerçevesi çizilen sınırlar dışında yürütmeye genel ve belirsiz bir kural koyma yetkisi verememesi hangi anayasal ilkenin gereğidir?', 'Yasama yetkisinin devredilmezliği', ['Yargı yetkisinin bağımsızlığı', 'İdarenin takdir yetkisi kuralı', 'Merkezden yönetim temel ilkesi'], 'Anayasa\'ya göre yasama yetkisi Türk Milleti adına TBMM\'nindir ve bu yetki yürütme veya başka bir organa devredilemez.'),
  ('İdarenin kuruluş ve görevlerinin kanunla düzenlenmesini ve idarenin kanuna dayanmadan işlem yapamamasını ifade eden idare hukuku ilkesi hangisidir?', 'Kanuni idare ilkesi', ['Yetki genişliği temel ilkesi', 'Hizmet yerinden yönetim ilkesi', 'İdari vesayet denetimi kuralı'], 'Kanuni idare ilkesi, idarenin hem teşkilatlanmasının hem de faaliyetlerinin yasal bir dayanağa bağlı olmasını zorunlu kılar.'),
  ('Bir suçun mağduru veya failinin vatandaşlık bağı bulunmayan yabancı bir unsuru barındıran özel hukuk uyuşmazlıklarında hangi ülke hukukunun uygulanacağını belirleyen dal hangisidir?', 'Milletlerarası özel hukuk', ['Devletler genel kamu hukuku', 'Anayasa yargısı hukuku', 'İcra ve iflas usul hukuku'], 'Milletlerarası özel hukuk, yabancılık unsuru taşıyan evlilik, sözleşme veya miras gibi özel hukuk ilişkilerinde yetkili mahkemeyi ve uygulanacak hukuku belirler.'),
  ('Devletlerin birbirleriyle ve uluslararası örgütlerle olan diplomatik ilişkilerini, antlaşmalarını ve deniz hukukunu inceleyen kamu hukuku dalı hangisidir?', 'Devletler genel hukuku', ['Milletlerarası özel hukuk', 'Karşılaştırmalı ticaret hukuku', 'İdari yargılama usul hukuku'], 'Devletler genel hukuku (uluslararası kamu hukuku), egemen devletler ve uluslararası kuruluşlar arasındaki hak ve yükümlülükleri düzenler.'),
  ('Mahkemece verilen kesinleşmiş bir alacak hükmünü borçlunun kendiliğinden yerine getirmemesi halinde devlet gücüyle tahsil usulünü düzenleyen hukuk dalı hangisidir?', 'İcra ve iflas hukuku', ['Ceza muhakemesi hukuku', 'Anayasa yargılaması hukuku', 'Milletlerarası tahkim hukuku'], 'İcra ve iflas hukuku, alacaklıların haklarını devletin cebri icra organları aracılığıyla nasıl elde edeceğini belirler.'),
  ('Suç şüphesinin öğrenilmesinden hükmün kesinleşmesine kadar soruşturma ve kovuşturma aşamalarının nasıl yürütüleceğini düzenleyen hukuk dalı hangisidir?', 'Ceza muhakemesi hukuku', ['Maddi ceza genel hukuku', 'Medeni yargılama usul hukuku', 'İdari yaptırımlar genel hukuku'], 'Ceza muhakemesi hukuku, maddi gerçeğe insan haklarına saygılı usullerle ulaşılmasını sağlayan yargılama kurallarını düzenler.'),
  ('Kanun önünde herkesin dil, ırk, renk, cinsiyet, siyasi düşünce ve inanç ayrımı gözetilmeksizin aynı hukuk kurallarına tabi olması hangi ilkeyle ifade edilir?', 'Eşitlik ilkesi', ['Sosyal devlet ilkesi', 'Demokratik meşruiyet ilkesi', 'Güçler ayrılığı temel ilkesi'], 'Anayasa\'nın 10. maddesinde düzenlenen eşitlik ilkesi, aynı hukuki durumdaki kişilere farklı ve ayrıcalıklı işlem yapılmasını yasaklar.'),
  ('Ceza hukukunda bir fiilin suç sayılabilmesi için kanundaki tanımın muğlak olmaması ve bireylerin neyin yasak olduğunu önceden öngörebilmesi hangi alt ilkenin gereğidir?', 'Belirlilik ilkesi', ['Alenilik ve açıklık ilkesi', 'Sözlülük ve doğrudanlık ilkesi', 'Cezaların infazda eşitliği ilkesi'], 'Belirlilik ilkesi, kanunilik ilkesinin ayrılmaz bir parçası olup muğlak ifadelerle keyfi cezalandırma yapılmasının önüne geçer.'),
  ('Bir vatandaş, belediyenin kendisine verdiği haksız yıkım kararına karşı iptal davası açtığında, mahkeme idarenin işlemini hangi temel ilke ışığında denetler?', 'Hukuk devleti ilkesi', ['Yasama üstünlüğü temel ilkesi', 'İdari takdirin mutlaklığı ilkesi', 'Kamu yararı karinesinin kesinliği'], 'Hukuk devleti ilkesi, idarenin tüm eylem ve işlemlerinin yargı denetimine tabi olmasını zorunlu kılar.'),
  ('Türkiye\'de kamu gelir ve giderlerinin Türkiye Büyük Millet Meclisi adına mali denetimini yapan, anayasal statüye sahip yüksek denetim organı hangisidir?', 'Sayıştay', ['Danıştay', 'Uyuşmazlık Mahkemesi', 'Devlet Denetleme Kurulu'], 'Sayıştay, merkezi yönetim bütçesi kapsamındaki kamu idareleri ile sosyal güvenlik kurumlarının hesaplarını TBMM adına denetler ve kesin hükme bağlar.'),
  ('Yargılamada tarafların mahkemeye sunulan delillerden haberdar olması, bunlar hakkında açıklama yapabilmesi ve hakimin bu açıklamaları dikkate alması hangi haktır?', 'Hukuki dinlenilme hakkı', ['Kamu hizmetine girme hakkı', 'Düşünceyi yayma özgürlüğü', 'Konut ve haberleşme hakkı'], 'Hukuki dinlenilme hakkı, tarafların yargılama sürecine etkin katılımını sağlayan temel usul güvencesidir.'),
  ('Anayasa Mahkemesinde bir kanunun yürürlüğe girmesinden sonra Cumhurbaşkanı, TBMM\'de en fazla üyeye sahip iki siyasi parti grubu veya TBMM üye tamsayısının beşte biri tarafından açılabilen denetim yolu hangisidir?', 'Soyut norm denetimi', ['Somut norm denetimi', 'Bireysel başvuru incelemesi', 'Yüce Divan ceza yargılaması'], 'Soyut norm denetimi (iptal davası), herhangi bir somut dava olmaksızın belirli anayasal aktörlerin kanunun Anayasa\'ya aykırılığı iddiasıyla açtığı davadır.'),
  ('Görülmekte olan bir davada uygulanacak kanun hükmünü Anayasa\'ya aykırı bulan yerel mahkemenin, davayı durdurarak konuyu Anayasa Mahkemesine taşıması hangi denetim yoludur?', 'Somut norm denetimi', ['Soyut norm denetimi', 'İdari işlem iptal davası', 'Olağanüstü temyiz başvurusu'], 'Somut norm denetimi (itiraz yolu), görülmekte olan bir uyuşmazlıkta uygulanacak hükmün anayasallığının incelenmesini sağlar.'),
  ('Cumhurbaşkanı, Cumhurbaşkanı yardımcıları ve bakanları görevleriyle ilgili suçlardan dolayı yargılama yetkisi Anayasa Mahkemesinin hangi sıfatına aittir?', 'Yüce Divan', ['İdari Dava Dairesi', 'Yüksek Hakem Kurulu', 'Genel Kurul Temyiz Dairesi'], 'Anayasa Mahkemesi, Anayasa\'da sayılan üst düzey devlet görevlilerini görevleriyle ilgili suçlardan dolayı Yüce Divan sıfatıyla yargılar.'),
  ('Devlet organlarının yasama, yürütme ve yargı şeklinde birbirinden ayrılması ve birbirini dengeleyip denetlemesini öngören anayasal tasarım hangi ilkeyle adlandırılır?', 'Kuvvetler ayrılığı', ['Hukukun üstünlüğü ilkesi', 'Üniter devlet yapısı kuralı', 'Parlamenter temsil prensibi'], 'Kuvvetler ayrılığı, iktidarın tek elde toplanarak özgürlükleri tehdit etmesini önlemek amacıyla devlet erklerini paylaştırır.'),
  ('Bireyin devletten eğitim, sağlık ve sosyal güvenlik gibi kamusal hizmetleri talep edebilmesini sağlayan haklar Jellinek\'in kuramında ne olarak adlandırılır?', 'Pozitif statü hakları', ['Negatif statü hakları', 'Aktif statü hakları', 'Mutlak koruma hakları'], 'Pozitif statü hakları (isteme hakları), devletin bireylere maddi ve toplumsal olanaklar sunmak için aktif harekete geçmesini gerektirir.'),
  ('1948 İnsan Hakları Evrensel Bildirgesi\'ni hazırlayan Birleşmiş Milletler İnsan Hakları Komisyonuna başkanlık ederek metnin mimarı sayılan isim kimdir?', 'Eleanor Roosevelt', ['Winston Churchill', 'Charles de Gaulle', 'Woodrow Wilson'], 'Eleanor Roosevelt, farklı kültür ve hukuk geleneklerinden delegelerin uzlaşmasını sağlayarak İHEB\'in hazırlanmasında öncü rol oynamıştır.'),
  ('İnsan Hakları Evrensel Bildirgesi (İHEB) hukuki niteliği bakımından bir antlaşma yerine Birleşmiş Milletler Genel Kurul kararı olduğu için ilk kabul edildiğinde hangi etkiye sahipti?', 'Tavsiye ve bildirim niteliğinde', ['Doğrudan yargısal yaptırımlı', 'Ulusal anayasaları ilga eden', 'Yalnızca Avrupa devletlerine zorunlu'], 'İHEB başlangıçta hukuken bağlayıcı bir sözleşme değil, ortak ilke bildirgesi olarak kabul edilmiş; zamanla uluslararası örf-adet hukukuna ve bağlayıcı ikiz sözleşmelere zemin olmuştur.'),
  ('İnsan Hakları Evrensel Bildirgesi\'ndeki ilkeleri hukuken bağlayıcı uluslararası sözleşmelere dönüştüren ve 1966\'da kabul edilen iki temel Birleşmiş Milletler metni "ikiz sözleşmeler" olarak bilinir; bunlardan biri Medeni ve Siyasal Haklar Sözleşmesi, diğeri hangisidir?', 'Ekonomik, Sosyal ve Kültürel Haklar Sözleşmesi', ['Soykırım Suçunun Önlenmesi ve Cezalandırılması Sözleşmesi', 'Çocuk Haklarına Dair Uluslararası Sözleşme', 'Kadınlara Karşı Her Türlü Ayrımcılığın Önlenmesi Sözleşmesi'], '1966\'da kabul edilen "Medeni ve Siyasal Haklara İlişkin Uluslararası Sözleşme" ile "Ekonomik, Sosyal ve Kültürel Haklara İlişkin Uluslararası Sözleşme" İHEB\'i bağlayıcı hukuka dönüştürmüştür.'),
  ('Birleşmiş Milletler tarafından 1989 yılında kabul edilerek 18 yaşın altındaki her bireyi hak öznesi olarak koruyan ve dünyada en çok devletin taraf olduğu sözleşme hangisidir?', 'Çocuk Haklarına Dair Sözleşme', ['Avrupa Sosyal Şartı Antlaşması', 'Cenevre Mültecilerin Statüsü Sözleşmesi', 'İşkenceye Karşı Birleşmiş Milletler Sözleşmesi'], '1989 tarihli Birleşmiş Milletler Çocuk Haklarına Dair Sözleşme, çocuğun yüksek yararı ilkesini temel alarak yaşama, gelişme, korunma ve katılım haklarını güvenceye alır.'),
  ('Birleşmiş Milletler tarafından 1979 yılında kabul edilerek kadınlara karşı kamusal ve özel alanda her türlü ayrımcılığın ortadan kaldırılmasını hedefleyen uluslararası sözleşme hangisidir?', 'CEDAW', ['AİHS', 'UNESCO Şartı', 'ILO Temel Şartı'], 'CEDAW (Kadınlara Karşı Her Türlü Ayrımcılığın Önlenmesi Sözleşmesi), toplumsal cinsiyet eşitliğini sağlamak üzere taraf devletlere pozitif yükümlülükler getirir.'),
  ('1951 yılında kabul edilerek ırkı, dini, tabiiyeti veya siyasi düşüncesi nedeniyle zulüm korkusuyla ülkesini terk eden kişilerin hukuki statüsünü belirleyen sözleşme hangisidir?', 'Cenevre Mülteciler Sözleşmesi', ['Avrupa İnsan Hakları Sözleşmesi', 'Medeni ve Siyasal Haklar Sözleşmesi', 'Viyana Antlaşmalar Hukuku Sözleşmesi'], '1951 Cenevre Sözleşmesi, mülteci tanımını yapmış ve mültecilerin zulüm görecekleri ülkeye zorla geri gönderilememesi (non-refoulement) ilkesini getirmiştir.'),
  ('İnsan haklarını tarihsel gelişimine göre birinci, ikinci ve üçüncü kuşak haklar şeklinde kavramsallaştıran Çek asıllı Fransız hukukçu kimdir?', 'Karel Vasak', ['Hans Kelsen', 'Georg Jellinek', 'Norberto Bobbio'], 'Karel Vasak, 1979\'da Fransız Devrimi\'nin özgürlük, eşitlik ve kardeşlik sloganlarından esinlenerek insan haklarını üç kuşak halinde sınıflandırmıştır.'),
  ('1215 Magna Carta\'nın 39. maddesinde geçen "hiçbir özgür insan dengi olanların yasal yargılaması veya ülke yasası olmadan tutuklanamaz, hapsedilemez" hükmü hangi modern ilkenin erken temelidir?', 'Kanuni ve adil yargılanma güvencesi', ['Sosyal güvenlik ve emeklilik hakkı', 'Çevre ve iklim koruma yükümlülüğü', 'Uluslararası tahkim zorunluluğu'], 'Magna Carta\'nın bu ünlü maddesi, keyfi tutuklamanın yasaklanması ve yasal yargılama (due process) fikrinin tarihsel kökünü oluşturur.'),
  ('Magna Carta Libertatum metninin tarihsel sınırları değerlendirildiğinde, hakların başlangıçta esasen hangi toplumsal kesimi doğrudan koruduğu görülür?', 'Özgür insanlar ve feodal baronlar', ['Toprağa bağlı tüm serfler ve köleler', 'Ülkedeki tüm kadın ve erkek yurttaşlar', 'Yabancı tüccarlar ve sömürge halkları'], 'Magna Carta, modern anlamda evrensel insan hakları belgesi olmayıp öncelikle kral karşısında baronların ve özgür kişilerin ayrıcalıklarını güvenceye almıştır.'),
  ('1628 yılında İngiliz Parlamentosunun Kral I. Charles\'a sunduğu ve parlamento onayı olmadan vergi konulmasını, keyfi hapis cezalarını yasaklayan belge hangisidir?', 'Haklar Dilekçesi', ['Magna Carta Libertatum Fermanı', 'Virginia Haklar Bildirgesi Metni', 'İnsan ve Yurttaş Hakları Bildirisi'], 'Sir Edward Coke\'un öncülüğünde hazırlanan 1628 Haklar Dilekçesi, İngiliz anayasal haklar geleneğinde Magna Carta ile Bill of Rights arasındaki önemli halkadır.'),
  ('1789 Fransız İnsan ve Yurttaş Hakları Bildirisi\'nin 16. maddesine göre "Hakların güvence altına alınmadığı ve kuvvetler ayrılığının belirlenmediği bir toplumda" aşağıdakilerden hangisi yoktur?', 'Anayasa', ['Hükümet', 'Ordu teşkilatı', 'Vergi sistemi'], 'Bildirinin 16. maddesi, maddi anlamda bir anayasanın varlığını yalnızca yazılı bir metne değil, hak güvencesi ve kuvvetler ayrılığına bağlar.'),
  ('1789 Fransız İnsan ve Yurttaş Hakları Bildirisi\'nin kadınları dışladığını savunarak 1791\'de "Kadın ve Kadın Yurttaş Hakları Bildirgesi"ni kaleme alan Fransız düşünür kimdir?', 'Olympe de Gouges', ['Simone de Beauvoir', 'Mary Wollstonecraft', 'Germaine de Staël'], 'Olympe de Gouges, 1789 Bildirisi\'ndeki yurttaşlık haklarının yalnızca erkeklere tanınmasını eleştirerek kadınların tam hukuki ve siyasal eşitliğini savunmuştur.'),
  ('"Temsilsiz vergi olmaz" ilkesi, vergilendirme yetkisinin halkın seçtiği temsilcilere ait olması gerektiğini savunarak hangi iki tarihsel süreçte belirleyici rol oynamıştır?', 'İngiliz anayasacılığı ve Amerikan Devrimi', ['Sanayi Devrimi ve Viyana Kongresi', 'Otuz Yıl Savaşları ve Vestfalya Barışı', 'Soğuk Savaş ve Helsinki Süreci'], 'Verginin parlamento onayıyla konulması fikri Magna Carta ve Bill of Rights\'ta şekillenmiş, Amerikan kolonilerinin İngiltere\'ye karşı bağımsızlık mücadelesinde sloganlaşmıştır.'),
  ('Türkiye, Avrupa İnsan Hakları Mahkemesine bireysel başvuru hakkını vatandaşlarına hangi yılda tanımıştır?', '1987', ['1954', '1961', '1999'], 'Türkiye 1987 yılında Avrupa İnsan Hakları Komisyonuna bireysel başvuru hakkını, 1990 yılında ise AİHM\'nin zorunlu yargı yetkisini kabul etmiştir.'),
  ('Bir bireyin hak ihlali iddiasıyla Avrupa İnsan Hakları Mahkemesine (AİHM) başvurabilmesi için öncelikle yerine getirmesi gereken temel kabul edilebilirlik şartı hangisidir?', 'İç hukuk yollarının tüketilmesi', ['Birleşmiş Milletler onayının alınması', 'Avrupa Parlamentosuna dilekçe verilmesi', 'Devlet başkanından izin belgesi alınması'], 'İkincillik ilkesi gereği AİHM\'ye başvurmadan önce ulusal yargı mercilerindeki (Türkiye\'de AYM bireysel başvurusu dahil) etkin iç hukuk yolları tüketilmelidir.'),
  ('Avrupa Konseyi tarafından 1961 yılında kabul edilerek Avrupa İnsan Hakları Sözleşmesi\'ni ekonomik ve sosyal haklar alanında tamamlayan belge hangisidir?', 'Avrupa Sosyal Şartı', ['Roma Statüsü Antlaşması', 'Schengen Serbest Dolaşım Sözleşmesi', 'Lizbon Avrupa Birliği Antlaşması'], 'Avrupa Sosyal Şartı, çalışma koşulları, sendikal haklar, sosyal güvenlik ve barınma gibi ikinci kuşak hakları güvence altına alır.'),
  ('Doğal hukuk kuramına göre insan haklarının kaynağı aşağıdakilerden hangisidir?', 'İnsanın doğuştan sahip olduğu onur', ['Yalnızca devletin lütfettiği kanunlar', 'Yöneticilerin keyfi takdir kararları', 'Belirli zümrelere tanınan ayrıcalıklar'], 'Doğal hukuk anlayışı, insan haklarının devlet tarafından yaratılmadığını, insanın doğuştan sahip olduğu ve devletin yalnızca tanıyıp korumakla yükümlü olduğu haklar olduğunu savunur.'),
  ('İnsan haklarının "bölünmezliği ve karşılıklı bağımlılığı" ilkesi aşağıdakilerden hangisini vurgular?', 'Medeni, siyasal ve sosyal hakların birbirini tamamladığını', ['Yalnızca siyasal hakların hukuki değere sahip olduğunu', 'Ekonomik hakların diğer hakları gereksiz kıldığını', 'Devletlerin istediği hak grubunu seçip diğerlerini yok sayabileceğini'], 'Bölünmezlik ilkesi, örneğin eğitim veya sağlık hakkı olmadan ifade ve seçme özgürlüğünün tam kullanılamayacağını, tüm hakların bir bütün olduğunu ifade eder.'),
  ('"İnsan haklarının evrenselliği" kavramı neyi ifade eder?', 'Her insanın nerede doğduğuna bakılmaksızın aynı temel haklara sahip olduğunu', ['Yalnızca uluslararası örgüt üyesi ülke yurttaşlarının hak sahibi olduğunu', 'Hakların her ülkenin geleneklerine göre tamamen ortadan kaldırılabileceğini', 'Sadece anayasal demokrasilerde yaşayan bireylerin insan onuru taşıdığını'], 'Evrensellik ilkesi, temel insan haklarının dil, din, ırk, cinsiyet veya uyruk ayrımı olmaksızın tüm insanlar için geçerli olduğunu belirtir.'),
  ('"Hakların devredilmezliği ve vazgeçilmezliği" ilkesine göre bir kişi kendi rızasıyla aşağıdaki işlemlerden hangisini hukuken geçerli biçimde yapamaz?', 'Kendini bir başkasının kölesi yapma sözleşmesi imzalamak', ['Sahip olduğu taşınmaz mülkü satarak devretmek', 'Belirli bir borç ilişkisinden alacak hakkını temlik etmek', 'Bir dernek üyeliğinden kendi isteğiyle istifa etmek'], 'Temel insan hakları kişiye sıkı sıkıya bağlıdır; kişi kendi özgür iradesiyle dahi köleleşemez veya yaşama hakkından hukuken vazgeçemez.'),
  ('İkinci Dünya Savaşı\'ndan sonra insanlığa karşı suçlar ve savaş suçlarından dolayı bireysel uluslararası ceza sorumluluğunu tarihte ilk kez işleten mahkeme hangisidir?', 'Nürnberg Uluslararası Askeri Mahkemesi', ['Avrupa İnsan Hakları Mahkemesi', 'Lahey Sürekli Tahkim Mahkemesi', 'Avrupa Toplulukları Adalet Divanı'], '1945-1946 Nürnberg yargılamaları, "üst emrini yerine getirdim" savunmasının insanlığa karşı suçlarda sorumluluğu kaldırmayacağını uluslararası hukuka yerleştirmiştir.'),
  ('Devletler arasındaki hukuki uyuşmazlıkları çözmekle görevli olan ve Birleşmiş Milletlerin başlıca yargı organı sayılan, merkezi Lahey\'deki mahkeme hangisidir?', 'Uluslararası Adalet Divanı', ['Avrupa İnsan Hakları Mahkemesi', 'Uluslararası Ceza Mahkemesi', 'Avrupa Birliği Adalet Divanı'], 'Uluslararası Adalet Divanı (UAD), bireysel başvurulara değil yalnızca devletler arasındaki uluslararası hukuk uyuşmazlıklarına bakar ve BM organlarına danışma görüşü verir.'),
  ('Bireylerin idarenin haksız işlem ve tutumlarına karşı yargıya gitmeden önce başvurabildiği, bağımsız inceleme yapıp tavsiye kararları veren kurum Türkiye\'de nasıl adlandırılır?', 'Kamu Denetçiliği Kurumu', ['Anayasa Mahkemesi Başkanlığı', 'Uyuşmazlık Mahkemesi Kurulu', 'Yüksek Hakem Heyeti Başkanlığı'], 'Ombudsmanlık sisteminin Türkiye\'deki karşılığı olan Kamu Denetçiliği Kurumu, 2010 anayasa değişikliğiyle kurulmuştur ve idareyi hukuka ve hakkaniyete uygunluk açısından inceler.'),
  ('Bir devletin sınırları içindeki herkesin temel haklarını yalnızca kendi müdahalesinden korumakla kalmayıp, üçüncü kişilerin ihlallerine karşı da etkili önlem almasına ne ad verilir?', 'Devletin pozitif yükümlülüğü', ['Devletin diplomatik dokunulmazlığı', 'Yasama organının takdir serbestisi', 'İdarenin kamulaştırma yetkisi'], 'İnsan hakları hukukunda pozitif yükümlülük, devletin yaşam hakkı veya özel hayat gibi hakları üçüncü kişilerin saldırılarından korumak için etkili yasal ve fiili tedbirler almasını gerektirir.'),
  ('Kişisel verilerin korunması, dijital ortamda unutulma hakkı ve biyoteknoloji karşısında insan onurunun korunması gibi yeni tartışma alanları doktrinde genellikle hangi kavramla anılır?', 'Dördüncü kuşak haklar', ['Birinci kuşak klasik haklar', 'Feodal dönem ayrıcalık hakları', 'Sadece özel hukuk sözleşme hakları'], 'Bilgi teknolojileri ve genetik mühendisliğindeki gelişmelerle ortaya çıkan dijital mahremiyet ve biyoetik güvenceleri literatürde dördüncü kuşak haklar kapsamında tartışılmaktadır.'),
  ('Osmanlı İmparatorluğu\'nda 1856 yılında ilan edilerek Müslüman ve gayrimüslim tebaa arasında kanun önünde, kamu görevlerinde ve vergide eşitlik öngören belge hangisidir?', 'Islahat Fermanı', ['Sened-i İttifak', 'Tanzimat Fermanı', 'Misak-ı Milli'], '1856 Islahat Fermanı, gayrimüslim yurttaşların hukuki ve toplumsal haklarını genişleterek eşit yurttaşlık anlayışına yönelik adımlar atmıştır.'),
  ('1975 yılında imzalanarak Soğuk Savaş döneminde Doğu ve Batı blokları arasında insan haklarına saygıyı uluslararası güvenlik ve iş birliğinin unsuru haline getiren belge hangisidir?', 'Helsinki Nihai Senedi', ['Atlantik Bildirisi Metni', 'Versay Barış Antlaşması', 'Cenevre Savaş Hukuku Sözleşmesi'], 'Avrupa Güvenlik ve İşbirliği Konferansı sonucunda imzalanan 1975 Helsinki Nihai Senedi, insan haklarını devletlerin salt iç işi olmaktan çıkaran önemli bir eşiktir.'),
  ('İnsan hakları hukukunda "ayrımcılık yasağı" ilkesi, dezavantajlı grupların (örneğin engellilerin) diğer bireylerle fiilen eşit fırsatlara kavuşması için özel tedbirler alınmasına engel midir?', 'Hayır, pozitif ayrımcılık caizdir', ['Evet, tüm özel destekler yasaktır', 'Sadece ekonomik krizlerde serbesttir', 'Yalnızca yerel yönetimlerce yasaktır'], 'Maddi eşitliği sağlamak amacıyla dezavantajlı kesimlere yönelik ölçülü özel önlemler (pozitif ayrımcılık) eşitlik ilkesinin ihlali değil gereğidir.'),
  ('1982 Anayasası\'na göre Türkiye Büyük Millet Meclisinin bir milletlerarası antlaşmayı uygun bulma kanunuyla onaylamasından sonra yürürlüğe koyma yetkisi kime aittir?', 'Cumhurbaşkanına', ['Anayasa Mahkemesine', 'Dışişleri Bakanlığına', 'Danıştay Genel Kuruluna'], 'Anayasa\'nın 104. maddesi uyarınca milletlerarası antlaşmaları onaylamak ve yayımlamak Cumhurbaşkanının görev ve yetkisindedir.'),
  ('Tarihte yazılı ilk büyük kanun derlemelerinden biri olan ve cezaların suça denk olmasını (kısas ilkesi) yazılı hukuk haline getiren Mezopotamya belgesi hangisidir?', 'Hammurabi Kanunları', ['On İki Levha Kanunları', 'Justinianus Derlemesi', 'Drakon Sert Yasaları'], 'MÖ 18. yüzyılda Babil Kralı Hammurabi tarafından taş steller üzerine yazdırılan kanunlar, hukukun yazılı ve aleni biçimde ilan edilmesinin en erken örneklerindendir.'),
  ('Bir sürücünün aşırı hız yaptığında kaza olabileceğini öngörmesine rağmen şoförlüğüne güvenerek kazanın olmayacağını düşünüp bir yayaya çarpması hangi kusurluluk türüne örnektir?', 'Bilinçli taksir', ['Doğrudan kast', 'Basit taksir', 'Kaçınılmaz kaza'], 'Fail neticeyi öngörmüş ancak gerçekleşmeyeceğine güvenmişse bilinçli taksir söz konusu olur.'),
  ('Meşru savunmadan yararlanabilmek için aşağıdakilerden hangisinin varlığı zorunludur?', 'Saldırının haksız olması', ['Saldırının mutlaka silahlı olması', 'Saldırganın ayırt etme gücüne sahip olması', 'Savunmanın saldırıdan sonra yapılması'], 'Meşru savunma için saldırının hukuka aykırı yani haksız olması ve savunmanın saldırı anında orantılı biçimde gerçekleşmesi şarttır.'),
  ('Dağda mahsur kalıp donma tehlikesi geçiren bir dağcının, hayatta kalmak için başkasının kilitli kulübesinin kapısını kırarak içeri girmesi ceza hukukunda hangi kavramla açıklanır?', 'Zorunluluk hali', ['Meşru savunma', 'İlgilinin rızası', 'Görevin ifası'], 'Zorunluluk (ıztırar) halinde kişi, kendisinin sebep olmadığı ağır ve muhakkak bir tehlikeden kurtulmak için üçüncü kişinin malına zarar verebilir.'),
  ('Ceza yargılamasında sanığın suçu işlediğine dair tam bir vicdani kanaate ulaşılamadığı ve tereddüt bulunduğu hallerde beraat kararı verilmesini gerektiren ilke hangisidir?', 'Şüpheden sanık yararlanır', ['Cezaların orantılılığı', 'Nispi eşitlik ilkesi', 'Kanun önünde eşitlik'], 'In dubio pro reo (şüpheden sanık yararlanır) ilkesi, kesin delil olmadan mahkumiyet kurulamayacağını ifade eder.'),
  ('Aşağıdakilerden hangisi ceza hukukunda "kıyas yasağı" ilkesinin doğrudan bir sonucudur?', 'Kanunda yazmayan bir fiilin benzer bir suça benzetilerek cezalandırılamaması', ['Hakimin sanığın lehine olan kanun hükümlerini uygulamaktan kaçınması', 'Aynı suçu işleyen kişilere farklı mahkemelerde farklı cezalar verilmesi', 'Kanunların yürürlüğe girdikten sonra sadece kamu görevlilerine uygulanması'], 'Suçta ve cezada kanunilik ilkesinin bir uzantısı olan kıyas yasağı, kanunda öngörülmeyen bir fiilin yorum yoluyla suç sayılmasını yasaklar.'),
  ('Suçun işlendiği tarihte yürürlükte olan kanun 5 yıl hapis öngörürken yargılama sürerken yürürlüğe giren yeni kanun aynı fiil için 3 yıl hapis öngörüyorsa hakim hangi ilke gereği 3 yıllık kanunu uygular?', 'Lehe kanunun geçmişe yürümesi', ['Aleyhe kanunun uygulanması', 'Kazanılmış hakların korunması', 'Sözleşme serbestisi ilkesi'], 'Ceza hukukunda sonradan yürürlüğe giren kanun failin lehine ise geçmişe yürüyerek o fiile uygulanır.'),
  ('Bir suçun işlenmesinden itibaren kanunda öngörülen sürenin geçmesiyle devletin o suçtan dolayı yargılama yapma yetkisinin düşmesine ne ad verilir?', 'Dava zamanaşımı', ['Hak düşürücü süre', 'Ceza zamanaşımı', 'Kovuşturma engeli'], 'Dava zamanaşımı, belirli bir süre geçtikten sonra kamu davasının açılamaması veya açılmış davanın düşmesi sonucunu doğurur.'),
  ('Kesinleşmiş bir mahkumiyet kararının kanunda belirtilen süre boyunca infaz edilememesi nedeniyle devletin cezayı çektirme yetkisinin sona ermesi aşağıdakilerden hangisidir?', 'Ceza zamanaşımı', ['Dava zamanaşımı', 'Etkin pişmanlık', 'Hükmün açıklanmasının geri bırakılması'], 'Ceza zamanaşımı, mahkemece verilip kesinleşen cezanın belirlenen sürede uygulanmaması halinde infaz olanağının kalkmasıdır.'),
  ('İstinaf ile temyiz kanun yolları arasındaki temel fark aşağıdakilerden hangisidir?', 'İstinaf hem olay hem hukuk denetimi yaparken temyiz sadece hukuk denetimi yapar', ['İstinaf yalnızca ceza davalarına bakarken temyiz yalnızca hukuk davalarına bakar', 'İstinaf kararlarını Anayasa Mahkemesi verirken temyiz kararlarını Danıştay verir', 'İstinaf başvurusu tamamen ücretsizken temyiz başvurusu zorunlu avukat gerektirir'], 'İstinaf mahkemesi gerekirse yeniden duruşma açıp tanık dinleyerek maddi gerçeği araştırabilir; temyiz mercii ise yalnız hukuki denetim yapar.'),
  ('Gözaltı ile tutuklama arasındaki en belirgin yetki farkı aşağıdakilerden hangisidir?', 'Gözaltı kararını cumhuriyet savcısı verebilirken tutuklama kararını yalnızca hakim verebilir', ['Gözaltı kararını kolluk amiri verirken tutuklama kararını emniyet müdürü verir', 'Gözaltı yalnızca sanıklar için uygulanırken tutuklama yalnızca tanıklar için uygulanır', 'Gözaltı süresi sınırsız olabilirken tutuklama süresi en fazla yirmi dört saattir'], 'Tutuklama kişi hürriyetini uzun süreli kısıtladığından Anayasa gereği yalnızca hakim veya mahkeme kararıyla mümkündür.'),
  ('Tutuklama yerine şüphelinin belirli aralıklarla karakola imza atması veya yurt dışına çıkışının yasaklanması şeklinde uygulanan koruma tedbiri hangisidir?', 'Adli kontrol', ['Şartlı tahliye', 'Denetimli serbestlik', 'Hükmün ertelenmesi'], 'Adli kontrol, tutuklama sebepleri bulunsa bile kişi özgürlüğünü daha az kısıtlayarak yargılamanın selametini sağlamaya yarayan tedbirdir.'),
  ('Ceza muhakemesinde soruşturma evresinde suç şüphesi altında bulunan kişiye "şüpheli" denirken kovuşturma evresinde bu kişiye ne ad verilir?', 'Sanık', ['Hükümlü', 'Mağdur', 'Katılan'], 'İddianamenin kabulü ile yargılama aşamasına geçildiğinde suçlanan kişi artık sanık sıfatını taşır.'),
  ('Bir kimsenin hakkında kesinleşmiş bir mahkumiyet kararı verildikten sonraki hukuki sıfatı aşağıdakilerden hangisidir?', 'Hükümlü', ['Sanık', 'Şüpheli', 'Müdafii'], 'Hükmün kesinleşmesiyle birlikte sanık sıfatı sona erer ve kişi infaz hukuku kapsamında hükümlü olarak adlandırılır.'),
  ('Suçtan doğrudan zarar gördüğünü belirterek yetkili makamlara başvuran ve şikayetçi olan kişiye ceza muhakemesinde ne ad verilir?', 'Müşteki', ['Sanık', 'Tanık', 'Kolluk görevlisi'], 'Müşteki (şikayetçi), suç nedeniyle hak ihlaline uğradığını ileri sürerek soruşturma başlatılmasını talep eden kişidir.'),
  ('Bir suç işlendikten sonra failin yalnızca o fiil için sonradan kurulan özel bir mahkemede yargılanması hangi temel hukuk ilkesini ihlal eder?', 'Kanuni hakim güvencesi', ['Sözlülük ilkesi', 'Silahların eşitliği', 'Makul sürede yargılanma'], 'Kanuni (doğal) hakim güvencesi gereği hiç kimse kanunen tabi olduğu mahkemeden başka bir merci önüne çıkarılamaz.'),
  ('Ceza muhakemesinde sanığın aleyhine olan deliller kadar lehine olan delillerin de savcılıkça toplanması ve tarafların eşit iddia-savunma imkanlarına sahip olması hangi ilkeyle ilgilidir?', 'Silahların eşitliği', ['Cezaların şahsiliği', 'Hukuki belirlilik', 'İdari vesayet'], 'Silahların eşitliği ilkesi, adil yargılanma hakkı kapsamında iddia ve savunma taraflarının dengeli koşullarda mücadele etmesini sağlar.'),
  ('Ceza hukukunda suç işlemeye karar veren bir kişinin icra hareketlerine başlamasına rağmen elinde olmayan nedenlerle suçu tamamlayamamasına ne ad verilir?', 'Teşebbüs', ['İştirak', 'İçtima', 'Gönüllü vazgeçme'], 'Elverişli hareketlerle suçun icrasına doğrudan başlayıp elde olmayan sebeplerle neticeye ulaşamamak suça teşebbüstür.'),
  ('Suç tamamlandıktan sonra failin pişmanlık göstererek zararı gidermesi veya suç ortaklarının yakalanmasına yardımcı olması halinde cezasında indirim yapılmasını sağlayan kurum hangisidir?', 'Etkin pişmanlık', ['Gönüllü vazgeçme', 'Genel af', 'Ön ödeme'], 'Etkin pişmanlık, gönüllü vazgeçmeden farklı olarak suç tamamlandıktan sonra ortaya çıkan ve kanunda öngörülen suçlarda ceza indirimi sağlayan bir kurumdur.'),
  ('Bir kimsenin suç işleme düşüncesi olmayan bir başkasını ikna ederek, teşvik ederek veya baskı kurarak suç işlemeye karar verdirmesine ne denir?', 'Azmettirme', ['Yardım etme', 'Müşterek faillik', 'Dolaylı faillik'], 'Azmettirme, başkasında suç işleme kararını oluşturan iştirak biçimidir ve azmettiren işlenen suçun cezası ile cezalandırılır.'),
  ('Bir suç işleme kararının icrası kapsamında değişik zamanlarda aynı kişiye karşı aynı suçun birden fazla kez işlenmesi aşağıdakilerden hangisidir?', 'Zincirleme suç', ['Bileşik suç', 'Müstakil suç', 'Kesintisiz suç'], 'Zincirleme (müteselsil) suçta fail tek bir cezaya çarptırılır ancak cezası belirli bir oranda artırılır.'),
  ('Fiili işlediği sırada on iki yaşını doldurmuş olup on beş yaşını doldurmamış bir çocuğun cezalandırılabilmesi için mahkeme öncelikle neyi araştırır?', 'Fiilin hukuki anlam ve sonuçlarını algılama ve davranışlarını yönlendirme yeteneğini', ['Çocuğun ailesinin gelir durumunu ve mesleğini', 'Mağdurun maddi zararının ne kadar olduğunu', 'Çocuğun okul başarı puanlarını ve devamsızlığını'], 'Bu yaş grubundaki çocuklarda kusur yeteneği (algılama ve yönlendirme gücü) gelişmişse indirimli ceza verilir, gelişmemişse ceza verilmez.'),
  ('Genel af ile özel af arasındaki en önemli fark aşağıdakilerden hangisidir?', 'Genel af mahkumiyetin tüm sonuçlarını silerken özel af yalnız cezanın infazını kısmen veya tamamen kaldırır', ['Genel af Cumhurbaşkanı tarafından çıkarılırken özel af yalnızca Anayasa Mahkemesi tarafından çıkarılır', 'Genel af sadece para cezalarını kapsarken özel af sadece müebbet hapis cezalarını kapsar', 'Genel af suçun mağdurunun rızasına bağlıyken özel af için yargı kararı gerekmez'], 'Özel afta hapis cezası hafifletilebilir veya kaldırılabilir ancak sabıka kaydı ve hak yoksunlukları gibi mahkumiyete bağlı sonuçlar devam edebilir.'),
  ('Yargılamanın açık yapılması temel kural olmakla birlikte aşağıdaki durumlardan hangisinde duruşmanın kapalı yapılmasına karar verilebilir?', 'Genel ahlakın veya kamu güvenliğinin kesin olarak gerekli kıldığı hallerde', ['Davanın çok uzun süreceği tahmin edilen her durumda', 'Sanığın avukatının duruşmaya geç kalması halinde', 'Hakimin kişisel olarak basından rahatsız olması durumunda'], 'Anayasa\'ya göre genel ahlakın, kamu güvenliğinin veya küçüğün korunmasının zorunlu kıldığı hallerde duruşmaların kısmen veya tamamen kapalı yapılmasına karar verilebilir.'),
  ('Aşağıdakilerden hangisi kamu hukukunun temel dalları arasında yer almaz?', 'Medeni hukuk', ['Anayasa hukuku', 'İdare hukuku', 'Vergi hukuku'], 'Medeni hukuk; kişiler, aile, miras ve eşya hukukunu kapsayan temel özel hukuk dalıdır.'),
  ('Aşağıdakilerden hangisi özel hukukun alt dallarından biri değildir?', 'Ceza hukuku', ['Borçlar hukuku', 'Ticaret hukuku', 'Devletler özel hukuku'], 'Ceza hukuku, suç ve cezaları belirleyerek kamu düzenini koruduğu için kamu hukuku dalıdır.'),
  ('Bir belediyenin yol genişletme çalışması için özel mülkiyetteki bir arsayı bedelini ödeyerek kamu mülkiyetine geçirmesi (kamulaştırma) hangi hukuk dalının konusudur?', 'İdare hukuku', ['Borçlar hukuku', 'Miras hukuku', 'Ticaret hukuku'], 'Kamu yararı amacıyla idarenin tek taraflı işlemle gerçekleştirdiği kamulaştırma idare hukuku kapsamındadır.'),
  ('Kanunların ve Cumhurbaşkanlığı kararnamelerinin Anayasa\'ya şekil ve esas bakımından uygunluğunu denetleyen ve bireysel başvuruları karara bağlayan yüksek mahkeme hangisidir?', 'Anayasa Mahkemesi', ['Yargıtay Genel Kurulu', 'Danıştay İdari Dava Daireleri', 'Uyuşmazlık Mahkemesi'], 'Anayasa Mahkemesi anayasal norm denetimi, siyasi parti kapatma, Yüce Divan yargılaması ve bireysel başvuru görevlerini yürütür.'),
  ('Anayasa Mahkemesi\'ne bireysel başvuru yapabilmek için aşağıdaki şartlardan hangisinin gerçekleşmiş olması kural olarak zorunludur?', 'Olağan kanun yollarının tüketilmiş olması', ['Başvurunun mutlaka avukat aracılığıyla yapılması', 'İhlalin yalnızca özel kişiler tarafından gerçekleştirilmesi', 'Konunun mutlaka tazminat davasıyla ilgili olması'], 'Bireysel başvuru ikincil nitelikte bir hak arama yoludur; öncelikle idari ve yargısal olağan başvuru yollarının tüketilmesi gerekir.'),
  ('1950 yılında Roma\'da imzalanan ve hak ihlallerine karşı bireylere uluslararası bir mahkemeye başvurma imkanı tanıyan bölgesel insan hakları belgesi hangisidir?', 'Avrupa İnsan Hakları Sözleşmesi', ['Amerikan Bağımsızlık Bildirgesi', 'Afrika İnsan ve Halkların Hakları Şartı', 'Kyoto İklim Protokolü'], 'Avrupa Konseyi çerçevesinde kabul edilen AİHS, Avrupa İnsan Hakları Mahkemesi aracılığıyla etkin bir denetim mekanizması kurmuştur.'),
  ('1776 yılında Amerika\'da kabul edilen ve yaşam, özgürlük ve mutluluğu arama hakkını devredilemez doğal haklar olarak tanımlayan belge hangisidir?', 'Amerikan Bağımsızlık Bildirgesi', ['Magna Carta Libertatum', 'Haklar Dilekçesi', 'Viyana Kongresi Kararları'], 'Thomas Jefferson\'ın kaleme aldığı Amerikan Bağımsızlık Bildirgesi, doğal haklar felsefesini siyasal bir metne dönüştürmüştür.'),
  ('Jellinek\'in hak sınıflandırmasında devletin bireyin özel alanına dokunmamasını gerektiren konut dokunulmazlığı ve haberleşme gizliliği hangi statü haklarıdır?', 'Negatif statü hakları', ['Pozitif statü hakları', 'Aktif statü hakları', 'Ekonomik talep hakları'], 'Negatif statü hakları (koruyucu haklar), devlete bireyin özgürlük alanına müdahale etmeme ödevi yükler.'),
  ('Bireyin devlet yönetimine katılmasını sağlayan seçme, seçilme, siyasi parti kurma ve kamu hizmetine girme hakları Jellinek\'in sınıflandırmasında ne olarak adlandırılır?', 'Aktif statü hakları', ['Negatif statü hakları', 'Pozitif statü hakları', 'Sosyal güvenlik hakları'], 'Aktif statü hakları (katılma hakları), yurttaşların siyasal karar alma süreçlerinde etkin rol oynamasını sağlar.'),
  ('Akıl hastalığı, akıl zayıflığı, yaş küçüklüğü veya sarhoşluk gibi nedenlerle makul surette davranma yeteneğinden yoksun olmayan kişinin sahip olduğu niteliğe ne ad verilir?', 'Ayırt etme gücü', ['Hukuki erginlik', 'Kişisel bağımsızlık', 'Yasal temsil yetkisi'], 'Ayırt etme gücü (temyiz kudreti), kişinin davranışlarının anlam ve sonuçlarını kavrayarak akla uygun hareket edebilmesidir.'),
  ('On altı yaşını doldurmuş ve ayırt etme gücüne sahip bir gencin kendi isteği ve velisinin rızasıyla mahkeme kararıyla ergin kılınması medeni hukukta hangi kavramla adlandırılır?', 'Kazai rüşt', ['Olağan erginlik', 'Yasal kısıtlama', 'Vasi tayini'], 'Kazai rüşt (mahkeme kararıyla ergin kılınma), 15 yaşını dolduran küçüğün menfaati ve velisinin rızasıyla mahkemece ergin sayılmasıdır.'),
  ('Türk Medeni Kanunu\'nda evlenme ile kazanılan erginlik hakkında aşağıdakilerden hangisi doğrudur?', 'Evlenme kişiyi ergin kılar ve boşanma halinde bu erginlik geri alınmaz', ['Evlenme kişiyi yalnızca eşinin izniyle ergin kılar ve boşanınca biter', 'Evlenme sadece yirmi yaşından büyük olanlara erginlik hakkı kazandırır', 'Evlenme erginlik sağlamaz ancak kişiye sadece ticari işlem yetkisi verir'], 'Evlenme kişiyi kesin olarak ergin kılar; evlilik sonradan boşanma veya ölümle sona erse dahi kişi ergin kalmaya devam eder.'),
  ('Ayırt etme gücü bulunmayan bir akıl hastasının veya bebek yaştaki bir çocuğun fiil ehliyeti kategorisi aşağıdakilerden hangisidir?', 'Tam ehliyetsiz', ['Sınırlı ehliyetsiz', 'Sınırlı ehliyetli', 'Tam ehliyetli'], 'Ayırt etme gücü olmayanlar tam ehliyetsizdir; yaptıkları hukuki işlemler kural olarak kesin hükümsüzdür.'),
  ('Akıl hastalığı, savurganlık, alkol veya uyuşturucu bağımlılığı, kötü yaşama tarzı ya da bir yıl ve daha uzun süreli özgürlüğü bağlayıcı ceza nedeniyle bir erginin fiil ehliyetinin mahkeme kararıyla sınırlandırılmasına ne denir?', 'Kısıtlama', ['Gaiplik kararı', 'Vasiyetname iptali', 'Kişiliğin sona ermesi'], 'Kısıtlama (hacir altına alma), kişinin kendisini veya ailesini yoksulluğa düşürme tehlikesine karşı mahkemece vasi atanması sürecidir.'),
  ('Kendisinden uzun zamandan beri haber alınamayan bir kimse hakkında gaiplik kararı talep edebilmek için son haber tarihinin üzerinden en az kaç yıl geçmesi gerekir?', 'Beş yıl', ['Bir yıl', 'Üç yıl', 'On yıl'], 'Son haber tarihinden itibaren 5 yıl geçmişse hakları ölüme bağlı olanlar mahkemeden gaiplik kararı isteyebilir.'),
  ('Mülkiyet ile zilyetlik arasındaki ilişkiyi en doğru biçimde açıklayan yargı aşağıdakilerden hangisidir?', 'Mülkiyet hukuki bir haktır, zilyetlik ise fiili hakimiyet durumudur; kiracı veya hırsız zilyet olabilir ama malik değildir', ['Mülkiyet sadece taşınır mallarda bulunur, zilyetlik ise yalnızca tapulu taşınmaz mallarda söz konusu olur', 'Zilyet olan her kişi aynı zamanda o eşyanın kanuni sahibi yani maliki kabul edilir', 'Mülkiyet devredilemez bir kişilik hakkıdır, zilyetlik ise sadece mahkeme kararıyla kazanılır'], 'Örneğin bir evi kiralayan kişi evde oturduğu için zilyettir, ancak evin tapu sahibi yani maliki ev sahibidir.'),
  ('Arkadaşından bir haftalığına ödünç aldığı bisikleti kullanan bir öğrenci, eşya hukuku bakımından bu bisiklet üzerinde hangi sıfatı taşır?', 'Fer\'i zilyet', ['Asli malik', 'İpotek alacaklısı', 'Müşterek malik'], 'Eşyayı malik sıfatıyla değil kira, ödünç veya rehin gibi sınırlı bir hakka dayanarak elinde tutan kişi fer\'i zilyettir.'),
  ('Bir taşınmazın maliki değişse bile alacaklıya alacağını o taşınmazın satış bedelinden öncelikle tahsil etme yetkisi veren sınırlı ayni hak hangisidir?', 'İpotek', ['Kira hakkı', 'Önalım hakkı', 'İntifa hakkı'], 'İpotek, halen mevcut veya ileride doğabilecek bir alacağı güvence altına almak amacıyla taşınmaz üzerinde kurulan rehin türüdür.'),
  ('Dernek ile vakıf arasındaki en temel yapısal fark aşağıdakilerden hangisidir?', 'Dernek bir kişi topluluğudur ve üyeleri vardır; vakıf ise bir mal topluluğudur ve üyeliği yoktur', ['Dernek mutlaka tek kişiyle kurulur; vakıf kurmak için en az elli kişi gereklidir', 'Dernekler yalnızca kamu hukuku tüzel kişisidir; vakıflar ise tüzel kişiliğe sahip değildir', 'Dernekler ticari kazanç paylaşımı yapar; vakıflar ise yalnızca siyasi faaliyet yürütür'], 'Dernek insan topluluğuna dayanır ve genel kurulu üyelerden oluşur; vakıf ise özgülenen malvarlığına dayanır ve tek kişi tarafından dahi kurulabilir.'),
  ('Derneklerin tüzel kişilik kazanma sistemi Türk hukukunda hangisine dayanır?', 'Serbest kuruluş (bildirim) sistemi', ['Bakanlar Kurulu izin sistemi', 'Mahkeme tescili sistemi', 'Anayasa Mahkemesi onay sistemi'], 'Dernekler kuruluş bildirimini, tüzüğünü ve gerekli belgeleri yerleşim yerinin bulunduğu en büyük mülki amire verdikleri anda tüzel kişilik kazanırlar.'),
  ('Medeni hukukta herkesin haklarını kullanırken ve borçlarını yerine getirirken uymak zorunda olduğu objektif dürüstlük ve makul insan davranışı ilkesine ne ad verilir?', 'Dürüstlük kuralı', ['Subjektif iyi niyet', 'Ahde vefa ilkesi', 'Sözleşme serbestisi'], 'TMK m. 2\'de düzenlenen dürüstlük kuralı (objektif iyi niyet), hakların kullanılmasında ve borçların ifasında dürüst, namuslu bir orta insan gibi davranmayı gerektirir.'),
  ('Bir hakkın açıkça kötüye kullanılmasını hukuk düzeninin korumaması kuralı hangi temel medeni hukuk ilkesiyle doğrudan bağlantılıdır?', 'Dürüstlük kuralı', ['Şekle bağlılık kuralı', 'Aleniyet ilkesi', 'İspat yükü kuralı'], 'Hakkın sırf başkasına zarar vermek veya meşru bir menfaat olmadan kullanılması dürüstlük kuralına aykırıdır ve hakkın kötüye kullanılması yasağı kapsamına girer.'),
  ('Türk Medeni Kanunu\'nun 1. maddesine göre hakim, önüne gelen uyuşmazlıkta uygulanabilir bir kanun hükmü ve örf-adet hukuku kuralı bulamazsa nasıl karar verir?', 'Kendisi kanun koyucu olsaydı nasıl bir kural koyacak idiyse ona göre karar verir', ['Dava dosyasını karara bağlamadan reddedip meclise iade eder', 'Taraflar arasında kura çekerek uyuşmazlığı sonlandırır', 'Davalı tarafın haklı olduğuna dair otomatik beraat kararı verir'], 'Kanunda ve örf-adet hukukunda boşluk varsa hakim hukuk yaratma yetkisini kullanarak bilimsel görüşlerden ve yargı kararlarından yararlanıp hüküm kurar.'),
  ('Bir kimsenin sürekli kalma niyetiyle oturduğu yere medeni hukukta ne ad verilir?', 'Yerleşim yeri', ['Geçici konut', 'İkamet izni', 'Nüfus kütüğü'], 'Yerleşim yeri (ikametgah), bir kimsenin sürekli kalma niyetiyle oturduğu yerdir ve kural olarak bir kişinin aynı anda birden çok yerleşim yeri olamaz.'),
  ('Kişinin kendi soyundan gelen altsoy ve üstsoy arasındaki hısımlık türüne ne denir?', 'Üstsoy-altsoy kan hısımlığı', ['Yansoy kan hısımlığı', 'Kayın hısımlığı', 'Yapay hısımlık'], 'Anne, baba, büyükanne, çocuk ve torunlar gibi birbirinden gelen kimseler arasında üstsoy-altsoy (düz hat) kan hısımlığı vardır.'),
  ('İki kardeş arasındaki kan hısımlığının türü ve derecesi aşağıdakilerden hangisidir?', 'İkinci dereceden yansoy kan hısımlığı', ['Birinci dereceden üstsoy kan hısımlığı', 'Üçüncü dereceden yansoy kan hısımlığı', 'İkinci dereceden kayın hısımlığı'], 'Hısımlık derecesi doğumlardan hesaplanır; kardeşlerden ortak ata (anne/baba) 1 doğum, oradan diğer kardeşe 1 doğum olmak üzere toplam 2. derece yansoy hısımlığı vardır.'),
  ('Evlilik yoluyla eşlerden biri ile diğer eşin kan hısımları arasında doğan hısımlık türüne ne ad verilir ve boşanma halinde bu hısımlık nasıl etkilenir?', 'Kayın hısımlığı denir ve evlilik boşanma ile sona erse bile ortadan kalkmaz', ['Yansoy hısımlığı denir ve boşanma kesinleştiği anda kendiliğinden sona erer', 'Sözleşmesel hısımlık denir ve yalnızca ortak çocuk varsa devam eder', 'İsteğe bağlı hısımlık denir ve noter bildirimi ile iptal edilebilir'], 'Kayın (sıhri) hısımlığı evlenme ile doğar; evlilik ölüm veya boşanma ile sona erse de hukuken devam eder.'),
  ('Uluslararası Adalet Divanı\'nda (UAD) görülen çekişmeli davalarda kimler taraf olabilir?', 'Yalnızca devletler', ['Yalnızca bireyler ve sivil toplum kuruluşları', 'Çok uluslu şirketler ve uluslararası sendikalar', 'Yalnızca Birleşmiş Milletler personeli'], 'UAD Statüsü\'nün 34. maddesi uyarınca Divan önündeki çekişmeli davalarda yalnızca devletler taraf sıfatı taşıyabilir.'),
  ('Uluslararası Adalet Divanı (UAD), devletler arasındaki davaları çözmenin yanı sıra hangi önemli yetkiye sahiptir?', 'Birleşmiş Milletler organlarına ve yetkili uzmanlık kuruluşlarına hukuki konularda danışma görüşü vermek', ['Soykırım suçu işleyen bireyleri tutuklayarak hapis cezasına çarptırmak', 'Üye ülkelerin iç hukukundaki anayasal değişiklikleri doğrudan iptal etmek', 'Savaş bölgelerine Birleşmiş Milletler barış gücü askeri göndermek'], 'UAD\'nin çekişmeli yargı yetkisi dışında BM Genel Kurulu, Güvenlik Konseyi ve yetkili kuruluşların hukuki sorularına danışma görüşü verme yetkisi de vardır.'),
  ('Uluslararası Adalet Divanı (UAD) ile Uluslararası Ceza Mahkemesi (UCM) arasındaki en temel fark aşağıdakilerden hangisidir?', 'UAD devletler arası uyuşmazlıkları çözerken UCM ağır uluslararası suçları işleyen bireyleri yargılar', ['UAD Avrupa Konseyi\'ne bağlıyken UCM Avrupa Birliği\'nin resmi yargı organıdır', 'UAD sadece ticari sözleşmelere bakarken UCM sadece çevre kirliliği davalarına bakar', 'UAD kararları bağlayıcı değilken UCM devletlerin sınırlarını yeniden belirleme yetkisine sahiptir'], 'Her iki mahkemenin merkezi de Lahey\'de olmakla birlikte UAD devletler arası hukuki ihtilaflara, UCM ise bireylerin cezai sorumluluğuna bakar.'),
  ('Bir bireyin Avrupa İnsan Hakları Mahkemesi\'ne (AİHM) başvurabilmesi için öncelikle yerine getirmesi gereken temel kabul edilebilirlik şartı hangisidir?', 'İç hukuk yollarının tüketilmiş olması', ['Başvurucunun mutlaka Avrupa Birliği vatandaşı olması', 'İhlalin mutlaka özel bir şirket tarafından yapılmış olması', 'Başvuru için yüksek miktarda yargılama harcı yatırılması'], 'AİHM ikincil koruma mekanizmasıdır; başvurucu önce ilgili devletteki etkili olağan iç hukuk yollarını (örneğin Türkiye\'de AYM bireysel başvuru dahil) tüketmelidir.'),
  ('Avrupa Birliği hukukunun üye devletlerde yeknesak yorumlanmasını ve uygulanmasını sağlamakla görevli olan, merkezi Lüksemburg\'da bulunan yüksek yargı organı hangisidir?', 'Avrupa Birliği Adalet Divanı', ['Avrupa İnsan Hakları Mahkemesi', 'Uluslararası Adalet Divanı', 'Uluslararası Deniz Hukuku Mahkemesi'], 'Avrupa Birliği Adalet Divanı (ABAD), AB antlaşmalarının ve mevzuatının yorumlanması ile uygulanmasından sorumlu birlik yargı organıdır.'),
  ('Venedik Komisyonu\'nun çıkardığı görüş ve raporların hukuki niteliği hakkında aşağıdakilerden hangisi doğrudur?', 'Hukuken bağlayıcı değildir ancak yüksek bilimsel ve siyasi ağırlığa sahip danışma görüşleridir', ['Taraf ülkelerin anayasalarını doğrudan değiştiren bağlayıcı yargı hükümleridir', 'Yalnızca Avrupa Birliği üyesi devletlere para cezası kesen icrai kararlardır', 'Üye ülkelerin meclislerini feshetme yetkisi içeren yürütme emirleridir'], 'Venedik Komisyonu bir mahkeme değil danışma organıdır; görüşleri bağlayıcı olmamakla birlikte uluslararası saygınlığı nedeniyle anayasal reformlarda rehber kabul edilir.'),
  ('Venedik Komisyonu üyeleri hangi nitelik ve statü ile görev yaparlar?', 'Bağımsız anayasa ve uluslararası hukuk uzmanları olarak kişisel sıfatlarıyla', ['Ülkelerinin hükümetlerini temsil eden diplomatik büyükelçiler olarak', 'Avrupa Parlamentosu\'nda en çok oy alan siyasi parti liderleri olarak', 'Birleşmiş Milletler askeri gözlemci temsilcileri olarak'], 'Komisyon üyeleri üye devletlerce dört yıllığına atanır ancak hükümetlerinden talimat almaz, tamamen bağımsız uzman sıfatıyla çalışırlar.'),
  ('Kamu Denetçiliği Kurumu\'nun (Ombudsmanlık) kararlarının hukuki niteliği aşağıdakilerden hangisidir?', 'Bağlayıcı yargı kararı değildir; idareye yönelik tavsiye kararı niteliğindedir', ['İdari mahkeme kararlarını bozan kesin temyiz hükmü niteliğindedir', 'Kamu görevlilerini doğrudan hapis cezasına mahkum eden ceza hükmüdür', 'Kanunları iptal edebilen anayasal norm denetimi kararıdır'], 'Ombudsman bir mahkeme değildir; idarenin hatalı işlemlerini düzeltmesi için gerekçeli tavsiye kararları verir ve kamuoyu ile meclisi bilgilendirir.'),
  ('Türkiye\'de Kamu Denetçiliği Kurumu\'nun (KDK) görev alanına girmeyen yani inceleyemeyeceği işlemlerden biri aşağıdakilerden hangisidir?', 'Yargı yetkisinin kullanılmasına ilişkin mahkeme kararları', ['Belediyelerin sunduğu kamusal hizmetlerdeki aksaklıklar', 'Üniversitelerin öğrencilere yönelik idari işlemleri', 'Sosyal güvenlik kurumunun emeklilik işlemleriyle ilgili şikayetler'], 'KDK; yasama yetkisinin kullanılmasına ilişkin işlemler, yargı yetkisinin kullanılmasına ilişkin kararlar ve TSK\'nın sırf askeri nitelikteki faaliyetlerini inceleyemez.'),
  ('Türkiye\'de Kamu Başdenetçisi hangi organ tarafından ve kaç yıl görev yapmak üzere seçilir?', 'Türkiye Büyük Millet Meclisi tarafından dört yıllığına', ['Cumhurbaşkanı tarafından yedi yıllığına', 'Anayasa Mahkemesi Genel Kurulu tarafından beş yıllığına', 'Yargıtay Büyük Genel Kurulu tarafından altı yıllığına'], 'Anayasa\'nın 74. maddesi uyarınca Kamu Başdenetçisi TBMM tarafından gizli oyla dört yıl için seçilir.'),
  ('Birleşmiş Milletler tarafından 1989 yılında kabul edilen ve on sekiz yaşına kadar her insanın özel koruma, katılım ve gelişim haklarını güvence altına alan uluslararası sözleşme hangisidir?', 'Çocuk Haklarına Dair Sözleşme', ['Ekonomik ve Sosyal Haklar Sözleşmesi', 'Mültecilerin Hukuki Durumuna Dair Sözleşme', 'İşçi Sağlığı Uluslararası Sözleşmesi'], 'BM Çocuk Haklarına Dair Sözleşme, dünya tarihinde en fazla devlet tarafından onaylanan insan hakları antlaşmasıdır.'),
  ('Kadınlara karşı her türlü ayrımcılığın önlenmesini ve toplumsal yaşamın her alanında cinsiyet eşitliğinin sağlanmasını amaçlayan 1979 tarihli Birleşmiş Milletler sözleşmesinin yaygın kısaltması nedir?', 'CEDAW', ['UNESCO', 'UNICEF', 'INTERPOL'], 'CEDAW (Kadınlara Karşı Her Türlü Ayrımcılığın Önlenmesi Sözleşmesi), taraf devletlere ayrımcı yasa ve uygulamaları kaldırma yükümlülüğü getirir.'),
  ('Hukuk devletinin temel unsurlarından biri olan "hukuki güvenlik ilkesi" bireylere öncelikle neyi teminat altına alır?', 'Hukuk kurallarının açık, öngörülebilir ve istikrarlı olmasını; geçmişe etkili keyfi müdahalelerin yapılmamasını', ['Mahkemelerin verdiği bütün kararların hiçbir koşulda temyiz edilmemesini', 'Devletin tüm ekonomik faaliyetleri bizzat yürüterek özel mülkiyeti kaldırmasını', 'Vergi oranlarının her yıl geriye dönük biçimde artırılarak tahsil edilmesini'], 'Hukuki güvenlik ve belirlilik ilkeleri, yurttaşların davranışlarının hukuki sonuçlarını önceden bilebilmesini ve devlete güven duymasını sağlar.'),
];
